import Foundation

/// 行业与岗位本地词库：499 条行话，和技术词库合在一起参与匹配。
/// 选中某个行业时，该行业词条优先命中；选中「自动」则不偏向任何行业。
/// 数据由 Windows 版同一份词库生成，两边内容一致。
enum IndustryTerms {

    /// 行业代码与显示名，第一项是「自动（全部行业）」。
    static let builtinDomains: [(String, String)] = [
        ("auto", "自动（全部行业）"),
        ("edu", "教育培训"),
        ("ec", "电商运营"),
        ("fin", "金融财税"),
        ("law", "法律合规"),
        ("med", "医疗健康"),
        ("mfg", "制造工业"),
        ("car", "汽车"),
        ("estate", "房地产建筑"),
        ("hr", "人力资源"),
        ("jargon", "互联网职场黑话"),
        ("mkt", "市场营销"),
        ("logi", "物流供应链"),
        ("retail", "餐饮零售"),
        ("post-op", "运营岗"),
        ("post-pm", "产品岗"),
        ("post-dev", "研发岗"),
        ("post-design", "设计岗"),
        ("post-mkt", "市场岗"),
        ("post-sales", "销售岗"),
        ("post-hr", "人事行政岗"),
        ("post-fin", "财务岗"),
        ("post-cs", "客服岗"),
        ("post-pmgr", "项目管理岗")
    ]

    private static var cached: [Terminology.Term]?

    static func all() -> [Terminology.Term] {
        if let c = cached { return c }
        var list: [Terminology.Term] = []
        if let data = rawJSON.data(using: .utf8),
           let arr = try? JSONSerialization.jsonObject(with: data) as? [[String: Any]] {
            list = arr.map { item in
                Terminology.Term(n: item["n"] as? String ?? "",
                                 a: item["a"] as? String ?? "",
                                 d: item["d"] as? String ?? "",
                                 x: item["x"] as? String ?? "",
                                 c: item["c"] as? String ?? "",
                                 i: item["i"] as? String ?? "")
            }
        }
        cached = list
        return list
    }

    static func label(for key: String) -> String {
        for (k, v) in domains() where k == key { return v }
        return "自动（全部行业）"
    }

    static func isKnown(_ key: String) -> Bool {
        domains().contains { $0.0 == key }
    }

    /// 内置行业 + 用户自建行业/岗位。
    static func domains() -> [(String, String)] {
        return builtinDomains + UserDict.shared.industries.map { ($0.key, $0.label) }
    }

    private static let rawJSON = ##"""
[{"n":"学分银行","a":"学银","d":"把平时学习、培训、考证攒下的学分像存钱一样存起来，按规定换成学历课程的学分。","x":"像超市积分卡，零散攒的分最后能当钱花。","c":"教育培训","i":"edu"},{"n":"学时","a":"课时","d":"一门课要求上满的小时数，报名、结课、算学费都按它计量。","x":"像驾校的练车小时数，练够才能约考。","c":"教育培训","i":"edu"},{"n":"形成性评价","a":"过程性评价","d":"平时作业、测验、出勤都算进成绩，不只靠最后一次考试定输赢。","x":"像减肥不是年底称一次重，而是每天记体重。","c":"教育培训","i":"edu"},{"n":"终结性评价","a":"","d":"只在课程结束时考一次，用这一场考试决定最终成绩。","x":"像一顿自助吃到饱，前面不吃后面猛塞。","c":"教育培训","i":"edu"},{"n":"学情画像","a":"学员画像","d":"把学员的基础、进度、薄弱点整理成一张标签清单，用来分层教学和推荐课程。","x":"像体检报告，哪项指标偏了一眼就看得出来。","c":"教育培训","i":"edu"},{"n":"续报率","a":"","d":"一期课结束后，继续报下一期的学员占比，是教培最看重的健康度指标。","x":"像健身房年卡到期，还有多少人接着续卡。","c":"教育培训","i":"edu"},{"n":"结课率","a":"完课率","d":"报名的人里真正坚持到课程结束的比例。","x":"像买了菜谱，最后真做完的菜有几道。","c":"教育培训","i":"edu"},{"n":"双师课堂","a":"双师","d":"一位老师线上主讲，一位老师线下答疑和管纪律，两拨人配合上一节课。","x":"像手术台上的主刀医生加器械护士，一个动刀一个递工具。","c":"教育培训","i":"edu"},{"n":"OMO","a":"线上线下融合","d":"线上招生授课和线下教务服务打通，同一个学员两条线都留记录。","x":"像外卖和堂用同一张会员卡，在哪吃都算积分。","c":"教育培训","i":"edu"},{"n":"教研","a":"教学研究","d":"研究教什么、怎么教、怎么考，产出大纲、讲义和题库。","x":"像餐厅的研发厨房，负责定菜单和配方。","c":"教育培训","i":"edu"},{"n":"助学","a":"班主任服务","d":"给学员配班主任或学习顾问，催进度、答疑、代办报考手续。","x":"像健身私教盯着你练，不然容易半途而废。","c":"教育培训","i":"edu"},{"n":"主考院校","a":"","d":"自考里负责出题、阅卷、发毕业证的那所学校。","x":"像连锁店的品牌方，门店可以很多，牌子只有一块。","c":"教育培训","i":"edu"},{"n":"考纲","a":"考试大纲","d":"官方规定考试范围和各章分值的文件，复习要按它来。","x":"像考试前老师划的重点范围。","c":"教育培训","i":"edu"},{"n":"通过率","a":"合格率","d":"参加考试的人里及格的比例。","x":"像投篮命中率，投出去多少次进了多少。","c":"教育培训","i":"edu"},{"n":"招生蓄水","a":"蓄水","d":"把还没报名的潜在学员先圈进名单里养着，等开班再转化。","x":"像先把水存在池子里，开闸时才有水放。","c":"教育培训","i":"edu"},{"n":"试听课","a":"","d":"免费或低价让学员先上一节，用来判断要不要报名。","x":"像买鞋之前先试穿。","c":"教育培训","i":"edu"},{"n":"退费周期","a":"退款时效","d":"从学员提出退费到钱真正到账要多久，是口碑风险最大的环节。","x":"像退货之后等退款到账的那几天。","c":"教育培训","i":"edu"},{"n":"教学计划","a":"考试计划","d":"一个专业规定要修哪些课、多少学分、几年修完。","x":"像旅行路线图，先去哪后去哪都写清楚。","c":"教育培训","i":"edu"},{"n":"免考","a":"免试","d":"符合条件（比如已有本科学历）可以不参加某几门课的考试。","x":"像考过驾照的人可以免考交规。","c":"教育培训","i":"edu"},{"n":"加分政策","a":"","d":"符合条件（比如年龄满 25 岁）在录取时能多算几分。","x":"像会员日全场额外打九折。","c":"教育培训","i":"edu"},{"n":"学籍","a":"","d":"你在学校系统里的正式身份记录，注册之后才存在。","x":"像会员卡号，证明你确实是这儿的人。","c":"教育培训","i":"edu"},{"n":"预报名","a":"占位报名","d":"先交定金锁住名额，开班前再补齐余款。","x":"像抢演出票先付定金锁定座位。","c":"教育培训","i":"edu"},{"n":"带班量","a":"","d":"一个班主任同时带多少学员，带太多服务就会掉下来。","x":"像一个服务员同时看几桌。","c":"教育培训","i":"edu"},{"n":"课程包","a":"","d":"把几门课打包一起卖，比单买便宜。","x":"像套餐比单点划算。","c":"教育培训","i":"edu"},{"n":"结业证书","a":"","d":"读完课程发的证明材料，不等于学历文凭。","x":"像参加活动发的纪念章，不是毕业证。","c":"教育培训","i":"edu"},{"n":"学习计划表","a":"周计划","d":"把每科要学的内容排到具体哪一周，用来盯进度。","x":"像健身房的训练计划表。","c":"教育培训","i":"edu"},{"n":"GMV","a":"成交总额","d":"一段时间里卖出去的商品总金额，不扣退款也不扣成本。","x":"像流水账上的营业额，热闹不等于赚钱。","c":"电商运营","i":"ec"},{"n":"客单价","a":"AOV","d":"平均每位顾客一次花多少钱。","x":"像一桌客人的均摊消费。","c":"电商运营","i":"ec"},{"n":"复购率","a":"","d":"一段时间内买过两次以上的顾客占比。","x":"像店里回头客的比例。","c":"电商运营","i":"ec"},{"n":"动销率","a":"","d":"有货的商品里真正卖出去过的比例，用来判断库存压不压。","x":"像衣柜里这个季度真穿过的衣服有几件。","c":"电商运营","i":"ec"},{"n":"坑位费","a":"专场费","d":"在主播或达人直播间占一个商品位置先付的固定费用，佣金另算。","x":"像商场里的摊位租金，卖多卖少都得付。","c":"电商运营","i":"ec"},{"n":"转化漏斗","a":"转化路径","d":"从看到、点击、加购到下单，每个环节剩多少人，用来看哪一环在漏人。","x":"像一层层过筛子，看哪层堵住了。","c":"电商运营","i":"ec"},{"n":"履约时效","a":"","d":"从下单到送达用了多久，是用户体验的硬指标。","x":"像外卖承诺的送达时间，晚一分钟就被投诉。","c":"电商运营","i":"ec"},{"n":"退货率","a":"","d":"卖出去又退回来的比例，服饰类通常最高。","x":"像试穿之后放回架子的比例。","c":"电商运营","i":"ec"},{"n":"白牌","a":"无品牌商品","d":"没有品牌溢价、靠性价比卖货的商品，包装上看不到名气。","x":"像超市自有品牌，便宜但没人认得。","c":"电商运营","i":"ec"},{"n":"私域","a":"私域流量","d":"能自己直接触达的用户池，比如微信群、企微好友，不靠平台分发。","x":"像自己家的鱼塘，不用每次去海里捞。","c":"电商运营","i":"ec"},{"n":"投流","a":"信息流投放","d":"花钱买平台的曝光位，把商品推给可能买的人。","x":"像在人流最旺的路口租一块广告牌。","c":"电商运营","i":"ec"},{"n":"爆款","a":"","d":"单量远超同类、还能带来自然流量的那一款商品。","x":"像店里那道人人必点的招牌菜。","c":"电商运营","i":"ec"},{"n":"起量","a":"起量期","d":"订单从零开始明显往上走的那一段。","x":"像火刚点着的那一下，最难也最关键。","c":"电商运营","i":"ec"},{"n":"投产比","a":"ROI","d":"花一块钱广告费能带回多少销售额。","x":"像下注之后赢回来多少钱。","c":"电商运营","i":"ec"},{"n":"种草","a":"","d":"先让人对产品产生兴趣，再等他自己来搜来买。","x":"像先给邻居尝一口，他觉得好吃才来买。","c":"电商运营","i":"ec"},{"n":"详情页","a":"商品详情","d":"商品页里讲参数、卖点和售后那一版内容。","x":"像商品包装背面的说明。","c":"电商运营","i":"ec"},{"n":"主图","a":"首图","d":"搜索列表里第一眼看到的那张图，直接决定点击率。","x":"像店门口的招牌，好不好看决定进不进门。","c":"电商运营","i":"ec"},{"n":"关键词卡位","a":"","d":"花钱让自己的商品排在某个搜索词的前面。","x":"像在路口抢最好的那个摊位。","c":"电商运营","i":"ec"},{"n":"达人分销","a":"分佣带货","d":"让达人以拿提成的方式帮你卖，不先付坑位费。","x":"像让业务员按提成拿钱，卖不出去不花钱。","c":"电商运营","i":"ec"},{"n":"供应链履约","a":"履约","d":"从下单到发货这段的执行能力，包括备货、打包、物流。","x":"像餐厅从接单到出餐的后厨流程。","c":"电商运营","i":"ec"},{"n":"售后工单","a":"","d":"用户投诉或退换货产生的一条待处理记录。","x":"像医院挂号之后拿到的那张就诊单。","c":"电商运营","i":"ec"},{"n":"店铺权重","a":"","d":"平台给店铺的综合评分，由销量、评价、违规记录等决定，影响能拿到多少曝光。","x":"像学生的综合测评排名，排名高才有好的资源。","c":"电商运营","i":"ec"},{"n":"大促节奏","a":"","d":"一次大促分成预热、爆发、返场几个阶段的时间安排。","x":"像电影先点映、再首映、最后加映。","c":"电商运营","i":"ec"},{"n":"平销期","a":"日常销售","d":"没有大促的平常销售时段。","x":"像非节假日的平常生意。","c":"电商运营","i":"ec"},{"n":"库存周转天数","a":"","d":"一批货平均多少天能卖完。","x":"像冰箱里的菜多久吃完一轮。","c":"电商运营","i":"ec"},{"n":"应收账款","a":"应收","d":"货已经发出、钱还没收到的那些账单。","x":"像借出去还没还的钱，账上有、兜里没有。","c":"金融财税","i":"fin"},{"n":"账期","a":"付款周期","d":"供应商交货后多久能拿到钱，常见的有 30、60、90 天。","x":"像赊账时说好月底一起结。","c":"金融财税","i":"fin"},{"n":"保理","a":"应收账款保理","d":"把还没到期的应收账款打折卖给金融机构，先换出现金。","x":"像把还没到期的欠条低价换成现钱应急。","c":"金融财税","i":"fin"},{"n":"贴现","a":"票据贴现","d":"拿没到期的票据去银行换现金，银行扣掉这段等待时间的利息。","x":"像提前退保，要扣一笔手续费。","c":"金融财税","i":"fin"},{"n":"增值税专用发票","a":"专票","d":"可以用来抵扣进项税的那类发票，一般纳税人之间交易才开。","x":"像能抵现金的券，但只能对公使用。","c":"金融财税","i":"fin"},{"n":"进项抵扣","a":"抵扣","d":"采购时付掉的增值税，可以从该缴的税额里扣回来。","x":"像买料时付的税，卖货时能扣回来一部分。","c":"金融财税","i":"fin"},{"n":"现金流","a":"","d":"账上真正能动的钱进出情况，和账面利润不是一回事。","x":"像钱包里的进出，账面赚了钱也可能一时掏不出现金。","c":"金融财税","i":"fin"},{"n":"坏账准备","a":"","d":"预估一部分应收款收不回来，提前在账上留出缓冲。","x":"像知道有人可能不还钱，先偷偷留一笔备用。","c":"金融财税","i":"fin"},{"n":"授信额度","a":"授信","d":"银行或平台愿意借给你的上限。","x":"像信用卡额度，能刷但得还。","c":"金融财税","i":"fin"},{"n":"毛利率","a":"","d":"收入减掉直接成本之后剩下的比例，不含房租和人工。","x":"像卖菜的差价率，进价一块卖两块。","c":"金融财税","i":"fin"},{"n":"摊销","a":"折旧摊销","d":"一笔大支出按使用年限分摊到每个月，不一次性全算进当期。","x":"像买台机器用五年，账上分五年算成本。","c":"金融财税","i":"fin"},{"n":"转移定价","a":"转让定价","d":"关联公司之间交易时定的价格，常用来把利润放到税率低的地方。","x":"像左右口袋倒钱，看哪个口袋少交费。","c":"金融财税","i":"fin"},{"n":"票据背书","a":"背书","d":"把票据转给别人时在背面签章，责任跟着票据一起走。","x":"像转借条时签个名，出了事要担责。","c":"金融财税","i":"fin"},{"n":"资产负债率","a":"","d":"总负债占总资产的比例，看企业借的钱是不是太多。","x":"像房贷占家庭总资产几成。","c":"金融财税","i":"fin"},{"n":"流动比率","a":"","d":"短期能变现的资产够不够覆盖短期要还的钱。","x":"像钱包里的现金够不够还这个月信用卡。","c":"金融财税","i":"fin"},{"n":"收入确认","a":"","d":"按会计准则判断什么时候可以把一笔钱记成收入。","x":"像外卖真正送到手里，这一单才算完成。","c":"金融财税","i":"fin"},{"n":"递延收入","a":"","d":"钱已经收了但服务还没交付，先挂在账上不算收入。","x":"像办了年卡但还没开始上课。","c":"金融财税","i":"fin"},{"n":"税负率","a":"","d":"实际缴的税占收入的比例。","x":"像一顿饭的钱里税费占多少。","c":"金融财税","i":"fin"},{"n":"审计意见","a":"","d":"会计师事务所对报表是否可信给出的结论。","x":"像体检报告最后医生写的那句结论。","c":"金融财税","i":"fin"},{"n":"关联交易","a":"","d":"和自家关联公司之间的买卖，要单独披露。","x":"像左手和右手做生意，得说清公允不公允。","c":"金融财税","i":"fin"},{"n":"财务共享中心","a":"","d":"把各分公司的记账、报销集中到一个部门统一处理。","x":"像小区集中供暖，不用每家自己烧锅炉。","c":"金融财税","i":"fin"},{"n":"预算超支","a":"","d":"实际花的钱超过了批准的额度。","x":"像手机流量用超了，要另外扣钱。","c":"金融财税","i":"fin"},{"n":"诉讼时效","a":"","d":"权利受法律保护的时间窗口，过了这个期限再起诉，法院可能就不支持了。","x":"像优惠券有有效期，过期作废。","c":"法律合规","i":"law"},{"n":"不可抗力","a":"","d":"无法预见、无法避免、也无法克服的事件，出了事可以据此免责。","x":"像台风天航班取消，不算航司违约。","c":"法律合规","i":"law"},{"n":"表见代理","a":"","d":"明明没授权，但看起来像有授权，对方有理由相信，公司仍要认这笔交易。","x":"像有人穿着工服在店里收钱，顾客自然以为他是店员。","c":"法律合规","i":"law"},{"n":"缔约过失","a":"","d":"合同还没签成，一方在谈的过程中有过错造成对方损失，要赔。","x":"像看房谈好又临时反悔，让对方白跑一趟。","c":"法律合规","i":"law"},{"n":"连带责任","a":"","d":"几个责任人里任何一个人都要对全部债务负责，赔完再内部追偿。","x":"像几个人一起担保，谁有钱谁先还。","c":"法律合规","i":"law"},{"n":"举证责任倒置","a":"","d":"本来谁主张谁举证，特殊情形下反过来，要求对方证明自己没责任。","x":"像医疗纠纷里，由医院自证没过错，而不是病人去证明。","c":"法律合规","i":"law"},{"n":"仲裁条款","a":"","d":"合同里约定有争议去仲裁机构、不去法院的条款，一裁终局。","x":"像约定吵架找长辈评理，不去打官司。","c":"法律合规","i":"law"},{"n":"竞业限制","a":"竞业禁止","d":"离职后一段时间不能去对手公司，公司要按月给补偿。","x":"像分手后约定一段时间不见对方朋友，得给补偿才作数。","c":"法律合规","i":"law"},{"n":"尽职调查","a":"DD","d":"交易前把对方的财务、法律、业务查一遍，看有没有埋着坑。","x":"像买房前查产权和抵押情况。","c":"法律合规","i":"law"},{"n":"合规审查","a":"","d":"业务方案上线前，按法律法规和内部制度过一遍。","x":"像出门前检查证件带没带齐。","c":"法律合规","i":"law"},{"n":"违约金调整","a":"","d":"约定的违约金过高或过低，法院可以按实际损失改。","x":"像押金收得太离谱，可以协商退回来。","c":"法律合规","i":"law"},{"n":"善意取得","a":"","d":"不知情、付了合理价钱、手续齐全，就能合法拿到东西，原主人不能直接要回。","x":"像在正规店买到别人偷来的二手货，你可能不用还。","c":"法律合规","i":"law"},{"n":"合同解除权","a":"解约权","d":"满足约定或法定条件时，一方可以单方面终止合同。","x":"像租房合同写明欠租两月就可以解约。","c":"法律合规","i":"law"},{"n":"保密协议","a":"NDA","d":"约定双方不能把对方的内部信息往外说的文件。","x":"像答应朋友不把他的秘密说出去，还立了字据。","c":"法律合规","i":"law"},{"n":"格式条款","a":"","d":"由一方预先写好、对方只能接受的条款。","x":"像停车场门口的告示：进场即视为同意。","c":"法律合规","i":"law"},{"n":"知识产权归属","a":"","d":"成果的版权、专利权到底归谁，必须在合同里写清楚。","x":"像合伙开店前先说清招牌归谁。","c":"法律合规","i":"law"},{"n":"数据合规","a":"","d":"收集和使用个人信息要合法、只取必需、并且告知同意。","x":"像借别人东西前先说清用来干什么、用多久。","c":"法律合规","i":"law"},{"n":"行政处罚","a":"","d":"政府部门对违法行为作出的罚款、警告、吊证等处理。","x":"像交警开的罚单，不服可以申请复议。","c":"法律合规","i":"law"},{"n":"诉讼保全","a":"","d":"起诉时先申请冻结对方财产，防止他转移。","x":"像打官司前先把对方账户按住。","c":"法律合规","i":"law"},{"n":"调解","a":"","d":"第三方居中协调，双方各让一步达成协议。","x":"像邻里吵架找居委会说和。","c":"法律合规","i":"law"},{"n":"电子签章","a":"","d":"有法律效力的电子印章或电子签名。","x":"像网签合同上按的电子手印。","c":"法律合规","i":"law"},{"n":"反商业贿赂","a":"","d":"禁止用回扣、好处费换取交易。","x":"像比赛明令禁止给裁判塞钱。","c":"法律合规","i":"law"},{"n":"分级诊疗","a":"","d":"小病先去社区医院，大病再转上级医院，避免所有人都挤三甲。","x":"像快递先到驿站，再由驿站送上门。","c":"医疗健康","i":"med"},{"n":"门诊统筹","a":"","d":"看门诊的费用也能由医保按比例报销，不用住院才报。","x":"像小额消费也能用会员折扣。","c":"医疗健康","i":"med"},{"n":"起付线","a":"门槛费","d":"医保开始报销之前，自己要先掏够的金额。","x":"像运费满 99 才包邮。","c":"医疗健康","i":"med"},{"n":"封顶线","a":"最高支付限额","d":"医保一年最多给你报多少，超出部分自己承担。","x":"像保险赔付有上限封顶。","c":"医疗健康","i":"med"},{"n":"DRG 付费","a":"DIP|按病种付费","d":"医保按病种给医院打包付钱，不再按检查、药品逐项结算。","x":"像装修报包干价，超支医院自己扛。","c":"医疗健康","i":"med"},{"n":"集采","a":"带量采购","d":"医保把各医院的需求量凑在一起集中采购，用大订单换低价。","x":"像小区团购，量大自然便宜。","c":"医疗健康","i":"med"},{"n":"适应症","a":"","d":"某种药或疗法被批准用于哪些疾病。","x":"像电器的适用电压，用错型号要出问题。","c":"医疗健康","i":"med"},{"n":"临床路径","a":"","d":"某个病从入院到出院的标准治疗步骤和时间表。","x":"像菜谱的步骤，谁照着做出来的都差不多。","c":"医疗健康","i":"med"},{"n":"循证医学","a":"","d":"治疗方案要拿研究数据说话，不靠个人经验拍板。","x":"像判案要有证据，不能凭感觉。","c":"医疗健康","i":"med"},{"n":"靶向治疗","a":"","d":"针对肿瘤特定基因或蛋白的药物，比化疗更精准、副作用更小。","x":"像快递按门牌号送到户，而不是整条街乱投。","c":"医疗健康","i":"med"},{"n":"处方流转","a":"","d":"电子处方从医院流到药店，患者可以就近取药。","x":"像线上下单后到附近门店取货。","c":"医疗健康","i":"med"},{"n":"随访","a":"","d":"治疗结束后定期回访，看恢复情况和有没有复发。","x":"像买完东西之后的售后回访。","c":"医疗健康","i":"med"},{"n":"三甲医院","a":"","d":"国内医院等级里最高的一档，即三级甲等。","x":"像酒店里的五星级。","c":"医疗健康","i":"med"},{"n":"医保目录","a":"","d":"哪些药和诊疗项目可以用医保报销的那份清单。","x":"像餐厅的优惠券可用清单，不在单上的只能原价。","c":"医疗健康","i":"med"},{"n":"特需门诊","a":"","d":"加钱挂的专家号，服务更快更好，但多数项目报销比例低。","x":"像飞机的商务舱，多花钱换舒适。","c":"医疗健康","i":"med"},{"n":"并发症","a":"","d":"治病过程中或之后出现的其他病症。","x":"像修水管时不小心把墙皮碰掉了。","c":"医疗健康","i":"med"},{"n":"知情同意书","a":"","d":"治疗或手术前，医生说明风险和替代方案、患者签字的文件。","x":"像坐过山车前签的风险告知。","c":"医疗健康","i":"med"},{"n":"多学科会诊","a":"MDT","d":"几个科室的医生一起讨论同一个复杂病例，定统一方案。","x":"像几个老师一起给一道难题会诊。","c":"医疗健康","i":"med"},{"n":"院内感染","a":"","d":"住院期间在医院里新得的感染。","x":"像住酒店期间染上了别的客人的感冒。","c":"医疗健康","i":"med"},{"n":"药占比","a":"","d":"药品收入占医疗总收入的比例，用来控制乱开药。","x":"像一家店靠卖配件赚的钱占总营收多少。","c":"医疗健康","i":"med"},{"n":"床位周转率","a":"","d":"一张床一年能收治多少病人。","x":"像餐厅的翻台率。","c":"医疗健康","i":"med"},{"n":"康复期","a":"","d":"治疗结束到身体功能恢复的那段时间。","x":"像装修完工后还要通风晾一段时间。","c":"医疗健康","i":"med"},{"n":"OEE","a":"设备综合效率","d":"设备实际产出和理论最大产出的比值，用来看设备到底有没有被用满。","x":"像跑一趟的实际平均车速对比最高车速。","c":"制造工业","i":"mfg"},{"n":"节拍时间","a":"Takt","d":"产线必须每隔多久出一件产品，才能刚好满足客户需求。","x":"像快餐店高峰期每 30 秒必须出一份餐。","c":"制造工业","i":"mfg"},{"n":"良率","a":"合格率","d":"投进去的料里做出合格品的比例。","x":"像一锅做十个，成功几个。","c":"制造工业","i":"mfg"},{"n":"首件检验","a":"首检","d":"每批开工先做一件全尺寸检查，确认没问题再批量干。","x":"像打印前先试印一页，看看排版对不对。","c":"制造工业","i":"mfg"},{"n":"防呆","a":"poka-yoke","d":"从设计上让错误装不进去、漏不掉，不指望人不出错。","x":"像 U 盘插反了根本插不进去。","c":"制造工业","i":"mfg"},{"n":"看板管理","a":"Kanban","d":"用卡片或电子屏告诉每道工序该做什么、做多少、什么时候要。","x":"像餐厅传菜口的点单条，后厨照着做。","c":"制造工业","i":"mfg"},{"n":"安灯系统","a":"Andon","d":"工位一出问题就按灯呼叫，管理立刻到场处理。","x":"像飞机座位上的呼叫铃。","c":"制造工业","i":"mfg"},{"n":"工装夹具","a":"夹具","d":"加工时固定和定位零件的专用工具，保证每一件位置都一样。","x":"像切菜用的模具，切出来大小一致。","c":"制造工业","i":"mfg"},{"n":"工艺路线","a":"工艺卡","d":"一件产品从毛坯到成品要经过的工序顺序。","x":"像菜谱的步骤顺序，变了味道就不对。","c":"制造工业","i":"mfg"},{"n":"MES","a":"制造执行系统","d":"车间里的生产管理系统，管工单、报工和质量追溯。","x":"像餐厅的点单系统，前台下单后厨立刻看得见。","c":"制造工业","i":"mfg"},{"n":"5S","a":"","d":"整理、整顿、清扫、清洁、素养，车间现场管理的基本动作。","x":"像厨房收工前的清理规矩。","c":"制造工业","i":"mfg"},{"n":"呆滞料","a":"","d":"长期不用、白占着仓库的物料。","x":"像冰箱里放到过期的食材。","c":"制造工业","i":"mfg"},{"n":"BOM","a":"物料清单","d":"做一件产品需要哪些料、各需要多少。","x":"像菜谱前面的配料表。","c":"制造工业","i":"mfg"},{"n":"来料加工","a":"","d":"客户把料送来，你只负责加工、按件收加工费。","x":"像代客缝衣服，布是客人自己带的。","c":"制造工业","i":"mfg"},{"n":"齐套率","a":"","d":"一个工单需要的料齐了几成，不齐就开不了工。","x":"像做菜缺一样配料就下不了锅。","c":"制造工业","i":"mfg"},{"n":"换型时间","a":"","d":"一条产线从做 A 产品切换到 B 产品要停多久。","x":"像厨房做完一道菜再做下一道，要洗锅换灶。","c":"制造工业","i":"mfg"},{"n":"设备点检","a":"","d":"开机前按清单逐项检查设备状态。","x":"像出车前绕车看一圈。","c":"制造工业","i":"mfg"},{"n":"报废率","a":"","d":"做坏到只能扔掉的产品比例。","x":"像裁布时废掉的那些边角料。","c":"制造工业","i":"mfg"},{"n":"产能利用率","a":"","d":"实际产量占理论最大产能的比例。","x":"像一辆车到底坐满了没有。","c":"制造工业","i":"mfg"},{"n":"委外加工","a":"外协","d":"自己做不完的部分交给外面的厂做。","x":"像餐厅忙不过来，把部分菜交给中央厨房。","c":"制造工业","i":"mfg"},{"n":"工时定额","a":"","d":"做一件产品标准给多少工时，用来算工钱和排产。","x":"像外卖平台给的预计送达时间。","c":"制造工业","i":"mfg"},{"n":"精益生产","a":"","d":"把不增值的动作、等待和库存全部去掉。","x":"像把跑步路线上的绕路全删掉。","c":"制造工业","i":"mfg"},{"n":"三电","a":"","d":"电池、电机、电控，电动车最核心的三块。","x":"像人的心脏、肌肉和神经。","c":"汽车","i":"car"},{"n":"热失控","a":"","d":"电池温度失控后连锁升温，严重时会起火。","x":"像锅里的油温失控，冒烟起火。","c":"汽车","i":"car"},{"n":"增程","a":"增程式","d":"车轮由电机驱动，发动机只负责发电、不直接驱动车轮。","x":"像充电宝给手机供电，手机本身靠电池跑。","c":"汽车","i":"car"},{"n":"双离合","a":"DCT","d":"两套离合器交替工作，换挡快，但低速容易顿挫。","x":"像两个人轮流接力，衔接快，配合不好就卡。","c":"汽车","i":"car"},{"n":"底盘调校","a":"","d":"对悬架、转向、制动的参数做调整，决定开起来是软还是硬。","x":"像把床垫软硬调到合适。","c":"汽车","i":"car"},{"n":"整车 OTA","a":"OTA 升级","d":"通过网络给已经卖出去的车升级软件甚至新功能。","x":"像手机系统远程更新。","c":"汽车","i":"car"},{"n":"轴距","a":"","d":"前后轮中心之间的距离，影响车内空间和行驶稳定性。","x":"像两人抬担子的间距，宽了稳但转不开。","c":"汽车","i":"car"},{"n":"续航达成率","a":"","d":"实际能跑的里程和官方标称里程的比值。","x":"像手机标称待机三天，实际用一天半。","c":"汽车","i":"car"},{"n":"换电","a":"","d":"不充电，直接把没电的电池包换成满电的。","x":"像桶装水送新桶、换空桶。","c":"汽车","i":"car"},{"n":"电池包","a":"","d":"由很多电芯组成、带外壳和散热的一整个电池总成。","x":"像一箱鸡蛋连着托盘和缓冲棉。","c":"汽车","i":"car"},{"n":"电控","a":"","d":"控制电机和电池怎么工作的电子系统。","x":"像人的神经，负责把命令传到该动的地方。","c":"汽车","i":"car"},{"n":"快充协议","a":"","d":"车和充电桩商量怎么充电的规则，决定能充多快。","x":"像两个人先商量用哪种语言说话。","c":"汽车","i":"car"},{"n":"冷启动","a":"","d":"低温环境下车辆或系统的第一次启动。","x":"像冬天早上第一把打火最难。","c":"汽车","i":"car"},{"n":"车机","a":"","d":"车里的中控屏和它跑的那套系统。","x":"像把一台平板电脑装进了车里。","c":"汽车","i":"car"},{"n":"自动辅助驾驶","a":"智驾","d":"帮你保持车道、跟车、变道的功能，但人必须盯着随时接管。","x":"像定速巡航的升级版，司机不能睡。","c":"汽车","i":"car"},{"n":"三包","a":"","d":"包修、包换、包退的售后规定。","x":"像买了不满意能退换的承诺。","c":"汽车","i":"car"},{"n":"保值率","a":"","d":"开了几年之后卖二手能卖回原价的几成。","x":"像手机用两年还能卖多少钱。","c":"汽车","i":"car"},{"n":"容积率","a":"","d":"小区总建筑面积除以用地面积，数值越高住得越挤。","x":"像一间房里塞几个人。","c":"房地产建筑","i":"estate"},{"n":"楼面价","a":"","d":"土地总价除以可建面积，算出每平米房子摊到的地价。","x":"像包场费摊到每个客人头上。","c":"房地产建筑","i":"estate"},{"n":"装配式建筑","a":"","d":"墙板、楼梯在工厂预制好，运到工地像搭积木一样拼起来。","x":"像宜家家具的预制件现场组装。","c":"房地产建筑","i":"estate"},{"n":"预售制","a":"期房","d":"房子还没盖好就先卖，用购房款给工程回款。","x":"像电影预售票，上映前先付钱。","c":"房地产建筑","i":"estate"},{"n":"毛坯房","a":"","d":"只做好结构和基础水电，装修自己搞。","x":"像买半成品菜，回家自己下锅。","c":"房地产建筑","i":"estate"},{"n":"精装房","a":"","d":"开发商统一装修好再交付，拎包入住。","x":"像买成衣，直接就能穿。","c":"房地产建筑","i":"estate"},{"n":"验槽","a":"","d":"基础开挖后检查土质和标高是否符合设计，合格才能浇混凝土。","x":"像铺地板前先看地面平不平。","c":"房地产建筑","i":"estate"},{"n":"工期索赔","a":"","d":"因甲方或不可抗力拖了工期，施工方要求补时间和费用。","x":"像外卖因店家原因延迟，可以要求补偿。","c":"房地产建筑","i":"estate"},{"n":"交付标准","a":"","d":"合同里写明的交房条件，比如门窗品牌、层高、绿化率。","x":"像买车时那张配置单。","c":"房地产建筑","i":"estate"},{"n":"得房率","a":"","d":"套内能实际使用的面积占建筑面积的比例。","x":"像买一箱苹果，去掉箱子和泡沫还剩多少。","c":"房地产建筑","i":"estate"},{"n":"公摊面积","a":"公摊","d":"楼道、电梯、配电间这些公共部分摊到每户头上的面积。","x":"像合租时客厅也算进每个人的房租。","c":"房地产建筑","i":"estate"},{"n":"五证","a":"","d":"卖房必须齐备的五份许可证，缺一不能网签。","x":"像开餐厅要备齐营业执照和卫生许可。","c":"房地产建筑","i":"estate"},{"n":"网签","a":"","d":"在房管系统里正式登记买卖合同，才算走完法律程序。","x":"像领结婚证，办过酒席不等于合法。","c":"房地产建筑","i":"estate"},{"n":"资金监管","a":"","d":"购房款先放进监管账户，过户完成后才划给卖家。","x":"像网购的担保交易，确认收货才放款。","c":"房地产建筑","i":"estate"},{"n":"限购","a":"","d":"规定哪些人、最多能买几套房。","x":"像景区限流，一天只放多少人进。","c":"房地产建筑","i":"estate"},{"n":"交付验房","a":"验房","d":"交房时逐项检查质量，把问题列成清单要求整改。","x":"像提车时先绕车检查一遍再签收。","c":"房地产建筑","i":"estate"},{"n":"物业费起算","a":"","d":"从哪天开始交物业费，通常按交付通知书的日期。","x":"像租房从入住那天开始算房租。","c":"房地产建筑","i":"estate"},{"n":"OKR","a":"目标与关键结果","d":"定一个方向性目标，再配几个可量化的检验点。","x":"像跑步定下配速目标和分段成绩。","c":"人力资源","i":"hr"},{"n":"人才盘点","a":"","d":"定期把团队每个人的能力、业绩、潜力过一遍，决定培养和调整。","x":"像年底盘库，看清哪些货好卖、哪些压着。","c":"人力资源","i":"hr"},{"n":"胜任力模型","a":"","d":"某个岗位要做好需要哪些能力和行为标准。","x":"像招聘启事背后那条真正的合格线。","c":"人力资源","i":"hr"},{"n":"绩效校准","a":"打分校准","d":"各部门打分口径不同，开会横向拉齐，避免都给自家人打高分。","x":"像几个老师一起改卷，先统一评分标准。","c":"人力资源","i":"hr"},{"n":"人才梯队","a":"继任计划","d":"每个关键岗位都提前准备好一到两个接班人。","x":"像球队的替补席，主力伤了有人顶。","c":"人力资源","i":"hr"},{"n":"雇主品牌","a":"","d":"求职者对你的公司是什么印象。","x":"像一家店在街坊里的口碑。","c":"人力资源","i":"hr"},{"n":"人员编制","a":"编制","d":"一个部门允许招多少人，由预算和组织架构定。","x":"像公交车上的座位数，满了就不再上人。","c":"人力资源","i":"hr"},{"n":"人力成本率","a":"","d":"人力总支出占营收的比例。","x":"像一家店的工资占营业额几成。","c":"人力资源","i":"hr"},{"n":"离职面谈","a":"","d":"员工提出离职时的一次谈话，了解真实原因。","x":"像退房时问一句住得哪里不舒服。","c":"人力资源","i":"hr"},{"n":"岗位说明书","a":"JD","d":"写清这个岗位做什么、要求什么、向谁汇报。","x":"像家电说明书，写清用途和注意事项。","c":"人力资源","i":"hr"},{"n":"薪酬带宽","a":"","d":"一个职级允许的工资区间，新人和老手在区间里浮动。","x":"像同房型的房价，淡旺季不一样但有个上下限。","c":"人力资源","i":"hr"},{"n":"试用期工资","a":"","d":"试用期间的工资，法定不得低于转正后的八成。","x":"像试营业期打八折。","c":"人力资源","i":"hr"},{"n":"年终奖计提","a":"","d":"按业绩预先算出要发的年终奖并计入当期成本。","x":"像提前把过年的红包钱存起来。","c":"人力资源","i":"hr"},{"n":"培训生计划","a":"管培生","d":"招应届生集中培养一段时间，再定岗。","x":"像学徒工先跟着师傅学，学成了再独立上手。","c":"人力资源","i":"hr"},{"n":"弹性工作制","a":"","d":"在保证总工时的前提下可以自己安排上下班时间。","x":"像自助餐，几点去吃自己定。","c":"人力资源","i":"hr"},{"n":"员工满意度调研","a":"","d":"用匿名问卷了解大家对公司的真实感受。","x":"像餐厅门口的意见卡。","c":"人力资源","i":"hr"},{"n":"对齐","a":"","d":"几个人把各自的理解和口径统一，避免各做各的。","x":"像几个人对表，先把时间调成一样的。","c":"互联网职场黑话","i":"jargon"},{"n":"拉通","a":"串一下","d":"把分散在各团队的信息和流程串起来，让大家知道的是同一件事。","x":"像把几节车厢连成一列火车。","c":"互联网职场黑话","i":"jargon"},{"n":"抓手","a":"着力点","d":"能立刻用上力、还能带动全局的那个切入点。","x":"像提箱子时握住的那个把手。","c":"互联网职场黑话","i":"jargon"},{"n":"闭环","a":"形成闭环","d":"一件事从开始到有结果、有反馈、有人负责，走完一整圈。","x":"像寄快递要有签收，不能只发出去就算完。","c":"互联网职场黑话","i":"jargon"},{"n":"赋能","a":"","d":"给别人提供能力或资源，让他自己能把事做成。","x":"像教人钓鱼，而不是直接送鱼。","c":"互联网职场黑话","i":"jargon"},{"n":"颗粒度","a":"颗粒感","d":"一件事拆得多细，或者数据统计到多细的层级。","x":"像切菜，切丝还是切块，粗细不一样。","c":"互联网职场黑话","i":"jargon"},{"n":"复盘","a":"","d":"事情做完后回看过程，找出哪里做对、哪里做错。","x":"像球队赛后一起看录像回放。","c":"互联网职场黑话","i":"jargon"},{"n":"打法","a":"套路","d":"做成一件事的整体策略和出招顺序。","x":"像打牌时的出牌思路。","c":"互联网职场黑话","i":"jargon"},{"n":"组合拳","a":"","d":"几个动作一起上、互相配合来达成目标。","x":"像拳击里的连击，单出一拳不倒人。","c":"互联网职场黑话","i":"jargon"},{"n":"心智","a":"用户心智","d":"用户一想到某个需求时，第一个蹦出来的是谁。","x":"像一说可乐就想到某个牌子。","c":"互联网职场黑话","i":"jargon"},{"n":"破圈","a":"","d":"从原来的小圈子里扩散到更大的受众。","x":"像小店的招牌菜被外地人专程来吃。","c":"互联网职场黑话","i":"jargon"},{"n":"势能","a":"","d":"攒起来的势头和影响力，能让后面的事更省力。","x":"像下坡时的惯性，越滚越快。","c":"互联网职场黑话","i":"jargon"},{"n":"沉淀","a":"","d":"把经验、内容、数据留下来，下次能直接复用。","x":"像把汤慢慢熬出味道，不是喝完就倒掉。","c":"互联网职场黑话","i":"jargon"},{"n":"落地","a":"落下去","d":"从想法变成真正能执行、能上线的东西。","x":"像图纸变成一栋真房子。","c":"互联网职场黑话","i":"jargon"},{"n":"卡点","a":"","d":"挡住进度的那一个具体问题。","x":"像高速上堵住整条路的那辆车。","c":"互联网职场黑话","i":"jargon"},{"n":"排期","a":"","d":"把要做的事按时间和人力排进日历。","x":"像餐厅的订位表，几点几桌都排好。","c":"互联网职场黑话","i":"jargon"},{"n":"需求评审","a":"过需求","d":"开发之前把需求讲清楚、挑毛病、定范围的会。","x":"像装修前和设计师把方案过一遍。","c":"互联网职场黑话","i":"jargon"},{"n":"迭代","a":"","d":"一小步一小步地改，每一轮都留下能用的版本。","x":"像手机系统的小版本更新。","c":"互联网职场黑话","i":"jargon"},{"n":"冷启动","a":"","d":"一个新产品一个用户都没有时，怎么把第一波人拉进来。","x":"像新店开业第一天，门口一个人都没有。","c":"互联网职场黑话","i":"jargon"},{"n":"用户画像","a":"","d":"把目标用户的特点整理成一张标签清单，用来判断内容做给谁看。","x":"像相亲前列一张对方的条件清单。","c":"互联网职场黑话","i":"jargon"},{"n":"留存","a":"留存率","d":"用过的人过一段时间还会不会回来。","x":"像店的回头客比例。","c":"互联网职场黑话","i":"jargon"},{"n":"拉新","a":"","d":"想办法带来从没来过的新用户。","x":"像发传单把人拉进店。","c":"互联网职场黑话","i":"jargon"},{"n":"促活","a":"","d":"让已经沉默的老用户重新用起来。","x":"像给老会员发张券叫他回来。","c":"互联网职场黑话","i":"jargon"},{"n":"转化","a":"转化率","d":"从看到到完成目标动作（注册、下单）的比例。","x":"像进店的人里最后有多少买了东西。","c":"互联网职场黑话","i":"jargon"},{"n":"北极星指标","a":"","d":"全公司只盯的那一个核心数字。","x":"像开车时只看的那块速度表。","c":"互联网职场黑话","i":"jargon"},{"n":"需求池","a":"","d":"把所有待做的需求收在一起，按优先级排序的清单。","x":"像待办事项清单，先挑急的做。","c":"互联网职场黑话","i":"jargon"},{"n":"干系人","a":"相关方","d":"会被这件事影响、需要通知和商量的人。","x":"像装修时要打招呼的邻居和物业。","c":"互联网职场黑话","i":"jargon"},{"n":"里程碑","a":"","d":"项目里几个关键时间点。","x":"像长跑路上的公里牌。","c":"互联网职场黑话","i":"jargon"},{"n":"搭子","a":"","d":"临时找的、只在某件事上配合的伙伴。","x":"像约着一起打球的人，打完各回各家。","c":"互联网职场黑话","i":"jargon"},{"n":"向上管理","a":"","d":"主动让上级了解进度和难处，争取资源和支持。","x":"像给客户定期汇报，别等出事才说话。","c":"互联网职场黑话","i":"jargon"},{"n":"甩锅","a":"","d":"把出问题的责任推给别人。","x":"像几个人合伙干活，出错了都说不是自己那一步。","c":"互联网职场黑话","i":"jargon"},{"n":"背锅","a":"","d":"不是主要责任，却被算成责任人。","x":"像球队输了球，守门员一个人挨骂。","c":"互联网职场黑话","i":"jargon"},{"n":"曝光量","a":"展现量","d":"广告被看到多少次，不等于被记住。","x":"像传单印了多少张、发出多少张。","c":"市场营销","i":"mkt"},{"n":"点击率","a":"CTR","d":"看到的人里有多少点进去了。","x":"像发一百张传单，有几个人真的进店。","c":"市场营销","i":"mkt"},{"n":"千人成本","a":"CPM","d":"让一千个人看到这条广告要花多少钱。","x":"像按人头算的摊位费。","c":"市场营销","i":"mkt"},{"n":"投放素材","a":"素材","d":"广告用的图、视频和文案。","x":"像门店的橱窗怎么布置。","c":"市场营销","i":"mkt"},{"n":"落地页","a":"","d":"点了广告之后进的那个页面。","x":"像进了店门之后的第一个柜台。","c":"市场营销","i":"mkt"},{"n":"品牌资产","a":"","d":"品牌积累下来的认知、信任和联想。","x":"像老字号那块招牌本身值多少钱。","c":"市场营销","i":"mkt"},{"n":"定位","a":"市场定位","d":"你想在用户心里占住的那个位置。","x":"像货架上你占的那一格，旁边是谁很重要。","c":"市场营销","i":"mkt"},{"n":"卖点","a":"","d":"用户能听懂、又真正在意的那个好处。","x":"像菜单上最想让人点的那句话。","c":"市场营销","i":"mkt"},{"n":"传播矩阵","a":"","d":"在多个渠道同时铺内容，互相带流量。","x":"像同一个品牌在几个商圈同时开店。","c":"市场营销","i":"mkt"},{"n":"内容日历","a":"","d":"提前排好哪天发什么内容。","x":"像电视台的节目单。","c":"市场营销","i":"mkt"},{"n":"裂变","a":"","d":"让老用户带新用户，一环带一环地扩散。","x":"像一个人拉三个人进群。","c":"市场营销","i":"mkt"},{"n":"口碑","a":"","d":"用户主动说出去的好坏评价。","x":"像街坊邻居嘴里对你的评价。","c":"市场营销","i":"mkt"},{"n":"事件营销","a":"","d":"借一个大话题或活动来做传播。","x":"像借节日办一场活动把人吸引过来。","c":"市场营销","i":"mkt"},{"n":"竞品分析","a":"","d":"把对手的产品、价格、打法摸清楚。","x":"像开店前先去对面店里吃一顿。","c":"市场营销","i":"mkt"},{"n":"用户调研","a":"","d":"直接问用户想要什么、卡在哪一步。","x":"像上新菜之前先请老顾客试吃。","c":"市场营销","i":"mkt"},{"n":"品效合一","a":"","d":"既要品牌声量，也要当场带来转化。","x":"像既打广告又当场卖货。","c":"市场营销","i":"mkt"},{"n":"触达","a":"","d":"把信息真正送到用户眼前或手机上。","x":"像敲门把东西送到人手上。","c":"市场营销","i":"mkt"},{"n":"转化成本","a":"获客成本","d":"带来一个下单用户平均要花多少钱。","x":"像拉一个客人进店要花多少传单钱。","c":"市场营销","i":"mkt"},{"n":"AB 测试","a":"A/B 测试","d":"两个版本各给一部分人看，比哪个效果更好。","x":"像两种包装先各卖一周试试。","c":"市场营销","i":"mkt"},{"n":"投放回收期","a":"","d":"广告花出去的钱，多久能靠后续订单赚回来。","x":"像装修投的钱，几个月靠营业额赚回来。","c":"市场营销","i":"mkt"},{"n":"头程","a":"","d":"货物从工厂到目的国或保税仓那一段运输。","x":"像快递的第一段长途。","c":"物流供应链","i":"logi"},{"n":"尾程","a":"最后一公里","d":"送到用户手上的最后一段。","x":"像接力赛的最后一棒。","c":"物流供应链","i":"logi"},{"n":"清关","a":"报关","d":"货物进出境时向海关申报、缴税、被放行的过程。","x":"像过安检加登记，手续不全就过不去。","c":"物流供应链","i":"logi"},{"n":"保税仓","a":"","d":"货物先进保税区仓库，卖出去时才交税出库。","x":"像先把货放在门口的储物柜，卖了再取。","c":"物流供应链","i":"logi"},{"n":"在途库存","a":"","d":"已经在路上、还没到仓的货。","x":"像点了外卖，还在骑手车上。","c":"物流供应链","i":"logi"},{"n":"安全库存","a":"","d":"为应对波动额外留的底货。","x":"像家里常备一袋米，吃完再买就晚了。","c":"物流供应链","i":"logi"},{"n":"断货率","a":"缺货率","d":"顾客想买却买不到的比例。","x":"像想点的那道菜卖完了。","c":"物流供应链","i":"logi"},{"n":"越库","a":"越库作业","d":"货到仓不存放，直接分拨发走。","x":"像公交换乘，不进候车厅直接换下一趟。","c":"物流供应链","i":"logi"},{"n":"分拨中心","a":"","d":"把发往各地的包裹按目的地分开的中转场。","x":"像邮局的分拣台。","c":"物流供应链","i":"logi"},{"n":"干线运输","a":"","d":"城市之间的大批量运输。","x":"像城市间跑的高速大巴。","c":"物流供应链","i":"logi"},{"n":"共同配送","a":"拼车配送","d":"几家货主的货拼一辆车送。","x":"像几个人拼车走同一段路。","c":"物流供应链","i":"logi"},{"n":"逆向物流","a":"","d":"退货、回收、返修这类往回走的物流。","x":"像退快递，货从用户手里往回走。","c":"物流供应链","i":"logi"},{"n":"库位","a":"","d":"仓库里给每种货固定的存放位置编号。","x":"像图书馆每本书的架位号。","c":"物流供应链","i":"logi"},{"n":"拣货路径","a":"","d":"仓库里拿货走的路线，路线越短越快。","x":"像在超市按清单从入口走到收银台。","c":"物流供应链","i":"logi"},{"n":"装载率","a":"","d":"一辆车装了多少比例的空间或重量。","x":"像行李箱塞满没塞满。","c":"物流供应链","i":"logi"},{"n":"时效承诺","a":"","d":"对外承诺几天送到，超时要赔。","x":"像外卖的准时宝。","c":"物流供应链","i":"logi"},{"n":"冷链","a":"","d":"全程控温的运输，生鲜和药品要用。","x":"像出门给菜盖上冰袋。","c":"物流供应链","i":"logi"},{"n":"签收率","a":"","d":"发出的包裹里成功被签收的比例。","x":"像寄出去的信有多少封真的送到了。","c":"物流供应链","i":"logi"},{"n":"翻台率","a":"","d":"一张桌子一天能接待几拨客人。","x":"像停车位一天能停几辆车。","c":"餐饮零售","i":"retail"},{"n":"坪效","a":"","d":"每平米店面一天或一个月能做多少营业额。","x":"像算一平米能挣多少钱。","c":"餐饮零售","i":"retail"},{"n":"出品率","a":"","d":"进货的原料能做出多少可卖的成品。","x":"像一斤肉剔完还能出多少净肉。","c":"餐饮零售","i":"retail"},{"n":"损耗率","a":"","d":"变质、破损、偷拿造成的损失比例。","x":"像水果摊每天要扔掉的烂果。","c":"餐饮零售","i":"retail"},{"n":"备餐","a":"","d":"高峰到来之前，先把常用料和半成品准备好。","x":"像考试前先把笔和草稿纸摆好。","c":"餐饮零售","i":"retail"},{"n":"客诉","a":"顾客投诉","d":"顾客不满意而提出的投诉记录。","x":"像意见本上写下的抱怨。","c":"餐饮零售","i":"retail"},{"n":"堂食","a":"外带","d":"在店里吃，还是打包带走。","x":"像书在图书馆看，还是借回家看。","c":"餐饮零售","i":"retail"},{"n":"会员储值","a":"充值卡","d":"顾客先把钱充进卡里，之后消费直接扣。","x":"像健身卡先充钱再刷。","c":"餐饮零售","i":"retail"},{"n":"单店模型","a":"","d":"把一家店的投资、成本、收入结构算清楚的账。","x":"像开一家店的账本模板。","c":"餐饮零售","i":"retail"},{"n":"选址评估","a":"","d":"开店前看人流、租金、周边竞品，决定开在哪。","x":"像买房前先看地段和邻居。","c":"餐饮零售","i":"retail"},{"n":"标准化操作","a":"SOP","d":"把每个动作写成流程，谁来做结果都一样。","x":"像连锁店统一的配方和步骤。","c":"餐饮零售","i":"retail"},{"n":"中央厨房","a":"","d":"统一加工半成品，再配送到各门店。","x":"像总仓统一备货，各店只管最后一步。","c":"餐饮零售","i":"retail"},{"n":"排班","a":"","d":"按客流高低安排谁上哪个班。","x":"像公交按早晚高峰加开班次。","c":"餐饮零售","i":"retail"},{"n":"复购周期","a":"","d":"同一个顾客两次购买之间隔多久。","x":"像一袋米吃完大概要多久。","c":"餐饮零售","i":"retail"},{"n":"引流品","a":"引流款","d":"故意定价很低、用来把人吸引进店的商品。","x":"像超市门口赔本卖的鸡蛋。","c":"餐饮零售","i":"retail"},{"n":"菜品毛利率","a":"","d":"营业额减掉食材成本后剩下的比例。","x":"像卖一杯奶茶，料钱占几成。","c":"餐饮零售","i":"retail"},{"n":"流量池","a":"","d":"能反复从中取流量的入口集合，比如搜索、推荐、私域、投放渠道。","x":"像院子里几口井，打水不用每次现挖。","c":"运营岗","i":"post-op"},{"n":"公域","a":"","d":"平台掌握的流量场所，谁都能来，但要按平台规则买曝光或抢推荐。","x":"像商场中庭，人流很大，但地盘不是你的。","c":"运营岗","i":"post-op"},{"n":"私域承接","a":"承接","d":"把平台上来的人引导到自己能直接触达的地方，比如企业微信、社群。","x":"像把路过的客人请进自家客厅坐着。","c":"运营岗","i":"post-op"},{"n":"引流钩子","a":"钩子","d":"为了让人愿意留下联系方式或进群，先给的那点小好处。","x":"像超市门口那盘试吃。","c":"运营岗","i":"post-op"},{"n":"转化路径","a":"路径","d":"用户从看到广告到完成下单，中间经过的页面和动作顺序。","x":"像从店门口走到收银台的那条动线。","c":"运营岗","i":"post-op"},{"n":"落地页转化率","a":"","d":"打开落地页的人里，最后提交表单或下单的比例。","x":"像进店一百人，真正掏钱的有几个。","c":"运营岗","i":"post-op"},{"n":"表单留资","a":"留资","d":"用户填手机号、姓名等信息，把线索留下的那个动作。","x":"像看房先在前台登记电话。","c":"运营岗","i":"post-op"},{"n":"首单转化","a":"","d":"新用户第一次下单的比例，衡量拉来的人对不对路。","x":"像新客第一次进店就买了东西。","c":"运营岗","i":"post-op"},{"n":"用户分层","a":"","d":"按消费额、活跃度把人分成几组，不同组用不同打法。","x":"像衣柜按季节分开放，换季直接拿那一层。","c":"运营岗","i":"post-op"},{"n":"沉默用户","a":"","d":"一段时间没来、也没有任何互动的用户。","x":"像很久没联系的老朋友。","c":"运营岗","i":"post-op"},{"n":"唤醒","a":"召回","d":"用推送、短信、优惠把沉默用户叫回来。","x":"像给老顾客发张券，喊他回来吃饭。","c":"运营岗","i":"post-op"},{"n":"召回率","a":"","d":"被叫回来的那部分人，占沉默用户的比例。","x":"像发出去一百条消息，回来几个。","c":"运营岗","i":"post-op"},{"n":"用户生命周期","a":"","d":"用户从第一次接触、活跃、沉默到彻底流失的整个过程。","x":"像人的一生，有刚认识、常来往、渐渐不来。","c":"运营岗","i":"post-op"},{"n":"次日留存","a":"","d":"今天新增的用户，第二天还来的比例。","x":"像新同事第二天还来上班。","c":"运营岗","i":"post-op"},{"n":"七日留存","a":"","d":"新增用户到第七天还回来的比例，看产品和内容能不能留住人。","x":"像新办的健身卡，一周后还去不去。","c":"运营岗","i":"post-op"},{"n":"留存曲线","a":"","d":"把第 1 天到第 30 天的留存比例连成一条线，看什么时候开始走平。","x":"像退烧曲线，看哪天温度稳住。","c":"运营岗","i":"post-op"},{"n":"获客成本","a":"CAC","d":"带来一个有效新用户平均要花的钱。","x":"像发传单拉一个客人进店，摊到每人身上多少。","c":"运营岗","i":"post-op"},{"n":"GMV","a":"成交总额","d":"成交总额，包含还没付款、以及之后可能退货的部分。","x":"像收银机打出的总流水，不等于真正到手的钱。","c":"运营岗","i":"post-op"},{"n":"UV","a":"独立访客","d":"一段时间内来访的不同人数，同一个人来两次只算一个。","x":"像一天进店多少人，认人不认次数。","c":"运营岗","i":"post-op"},{"n":"PV","a":"浏览量","d":"页面被打开的次数，同一个人反复看会重复计。","x":"像一本书被翻了多少页。","c":"运营岗","i":"post-op"},{"n":"跳出率","a":"","d":"只看了这一页就离开的人的比例。","x":"像进店转一圈、什么都没问就走的客人。","c":"运营岗","i":"post-op"},{"n":"停留时长","a":"","d":"用户在一个页面或一次访问里待了多久。","x":"像客人在店里逛了多长时间。","c":"运营岗","i":"post-op"},{"n":"加购率","a":"","d":"把商品加入购物车的人，占访问者的比例。","x":"像把衣服拿进试衣间试。","c":"运营岗","i":"post-op"},{"n":"支付转化率","a":"","d":"下单的人里，最后真正付了钱的比例。","x":"像排到收银台又放下东西走人。","c":"运营岗","i":"post-op"},{"n":"秒杀","a":"","d":"限时限量低价卖，用紧迫感制造抢的氛围。","x":"像早市头一筐菜半价，抢完就恢复原价。","c":"运营岗","i":"post-op"},{"n":"拼团","a":"","d":"凑够人数才享受低价，用老用户去带新用户。","x":"像几个人合买一件，人越多价越低。","c":"运营岗","i":"post-op"},{"n":"优惠券核销率","a":"核销率","d":"发出去的券真正被用掉的比例。","x":"像发一百张代金券，有多少张真被撕下来用。","c":"运营岗","i":"post-op"},{"n":"券后价","a":"","d":"用完优惠券之后，用户实际支付的价格。","x":"像打完折再抹个零。","c":"运营岗","i":"post-op"},{"n":"会员权益","a":"","d":"付费或高等级会员能享受的特殊待遇。","x":"像机场贵宾厅，只有持卡的人能进。","c":"运营岗","i":"post-op"},{"n":"选题","a":"","d":"决定这一期内容做什么题目、给谁看。","x":"像餐厅定这周的菜单。","c":"运营岗","i":"post-op"},{"n":"爆文","a":"爆款内容","d":"阅读量远超日常、还能顺带带来大量新粉的内容。","x":"像店里那道突然天天排队的招牌菜。","c":"运营岗","i":"post-op"},{"n":"完播率","a":"","d":"看完整个视频的人占播放人数的比例。","x":"像电影有多少人坐到片尾字幕。","c":"运营岗","i":"post-op"},{"n":"互动率","a":"","d":"点赞、评论、转发的人数占看到内容的人数的比例。","x":"像讲完课有多少人举手提问。","c":"运营岗","i":"post-op"},{"n":"评论区运营","a":"","d":"在评论区引导话题、回复、置顶，让讨论热起来。","x":"像主持人在台下递话筒、接话茬。","c":"运营岗","i":"post-op"},{"n":"KOC","a":"关键意见消费者","d":"粉丝不多但在小圈子里说话有分量的普通用户。","x":"像小区里那个特别会推荐的邻居。","c":"运营岗","i":"post-op"},{"n":"PRD","a":"产品需求文档","d":"写清做什么、给谁用、怎么算做完的那份文档。","x":"像装修前的施工图加材料清单。","c":"产品岗","i":"post-pm"},{"n":"MRD","a":"市场需求文档","d":"说明为什么要做这个产品、市场有多大、跟谁抢。","x":"像开店前先做的商圈调查。","c":"产品岗","i":"post-pm"},{"n":"用户故事","a":"","d":"用一句话描述某个角色想完成什么事。","x":"像剧本里的一句台词：我是谁，我要干什么。","c":"产品岗","i":"post-pm"},{"n":"验收标准","a":"","d":"判断这个功能算不算做完的具体条件。","x":"像收货时对着清单一项项打勾。","c":"产品岗","i":"post-pm"},{"n":"原型","a":"原型图","d":"功能长什么样、点了会怎样的草图，能点但不能真用。","x":"像房子的样板间。","c":"产品岗","i":"post-pm"},{"n":"信息架构","a":"","d":"把内容按层级和分类摆好，决定用户怎么找东西。","x":"像图书馆的书架分区和编号。","c":"产品岗","i":"post-pm"},{"n":"需求优先级","a":"","d":"在人力有限的情况下决定先做哪个需求。","x":"像急诊分诊，先救最急的那个。","c":"产品岗","i":"post-pm"},{"n":"版本","a":"版本号","d":"一次发布所带的一组功能，用 1.0、2.0 这样的号码区分。","x":"像手机系统的第几代。","c":"产品岗","i":"post-pm"},{"n":"MVP","a":"最小可用产品","d":"只做最核心的那一小块，先验证到底有没有人要。","x":"像先摆个摊位试卖，不急着开店面。","c":"产品岗","i":"post-pm"},{"n":"用户旅程","a":"","d":"用户从知道、试用、付费到推荐别人的全过程地图。","x":"像一张从家门口到公司的完整路线图。","c":"产品岗","i":"post-pm"},{"n":"痛点","a":"","d":"用户现在最难受、最愿意花钱解决的那件事。","x":"像鞋里那颗石子，走一步硌一下。","c":"产品岗","i":"post-pm"},{"n":"爽点","a":"","d":"用起来顺、让人愿意主动夸的地方。","x":"像开瓶盖那一下的清脆声。","c":"产品岗","i":"post-pm"},{"n":"需求蔓延","a":"范围蔓延","d":"需求越加越多，范围失控，工期一拖再拖。","x":"像装修时不断加项目，预算一路爆掉。","c":"产品岗","i":"post-pm"},{"n":"需求变更","a":"","d":"已经排期或已经在开发的需求又被改掉。","x":"像菜都下锅了又要换菜谱。","c":"产品岗","i":"post-pm"},{"n":"埋点","a":"","d":"在关键位置埋统计代码，记录用户到底做了什么。","x":"像在门口装个计数器，看每天进多少人。","c":"产品岗","i":"post-pm"},{"n":"数据看板","a":"看板","d":"把关键指标集中显示的一屏图表。","x":"像汽车的仪表盘。","c":"产品岗","i":"post-pm"},{"n":"用户访谈","a":"","d":"一对一聊，问用户实际怎么用、在哪一步卡住。","x":"像医生问诊，先听病人自己说。","c":"产品岗","i":"post-pm"},{"n":"可用性测试","a":"","d":"让人真的去用，看他在哪里卡住、哪里点错。","x":"像让新员工照着说明书操作一遍。","c":"产品岗","i":"post-pm"},{"n":"竞品拆解","a":"","d":"把对手的产品逐页、逐功能拆开分析。","x":"像把对手的招牌菜买回来拆配料。","c":"产品岗","i":"post-pm"},{"n":"功能清单","a":"","d":"把所有功能列成一张表，标清状态和负责人。","x":"像装修时的材料清单。","c":"产品岗","i":"post-pm"},{"n":"场景化","a":"","d":"围绕一个具体使用场景来设计，而不是往上堆功能。","x":"像按「下雨天接孩子」这个场景去设计一辆车。","c":"产品岗","i":"post-pm"},{"n":"线上问题","a":"","d":"已经上线之后，用户遇到或反馈的故障。","x":"像开张营业后客人当场发现的毛病。","c":"产品岗","i":"post-pm"},{"n":"需求澄清","a":"过需求","d":"开发动手之前，把不清楚的地方一条条问明白。","x":"像做菜前先问清有没有忌口。","c":"产品岗","i":"post-pm"},{"n":"提测","a":"","d":"开发把做完的功能交给测试去验证，进入测试环节。","x":"像厨师把菜端到窗口，等质检尝。","c":"研发岗","i":"post-dev"},{"n":"联调","a":"","d":"前端和后端、或者两个系统之间，把接口接起来当场调试。","x":"像两家店对账，一笔一笔核。","c":"研发岗","i":"post-dev"},{"n":"冒烟测试","a":"冒烟","d":"上线前把最核心的几条路径跑一遍，先看能不能跑通。","x":"像开车前先点火听声音，能着车再上路。","c":"研发岗","i":"post-dev"},{"n":"回归测试","a":"回归","d":"改完一个地方后，把原来能用的功能再验一遍，确认没被改坏。","x":"像修完水管，把家里所有水龙头都开一遍。","c":"研发岗","i":"post-dev"},{"n":"测试覆盖率","a":"覆盖率","d":"代码里有多少比例被测试跑到过。","x":"像一张卷子有多少道题被检查过。","c":"研发岗","i":"post-dev"},{"n":"预发环境","a":"预发","d":"和线上几乎一样、但真实用户进不来的一套环境，用来最后验一遍。","x":"像演出前的带妆彩排。","c":"研发岗","i":"post-dev"},{"n":"生产环境","a":"线上","d":"真实用户在用的那套系统，出事影响最大。","x":"像已经开门营业的店面。","c":"研发岗","i":"post-dev"},{"n":"发版窗口","a":"","d":"规定允许发布的时间段，一般挑流量低的时候。","x":"像只允许在打烊后装修。","c":"研发岗","i":"post-dev"},{"n":"变更审批","a":"","d":"改线上配置或数据前要先走一道审批，留痕可追溯。","x":"像动大手术前要家属签字。","c":"研发岗","i":"post-dev"},{"n":"P99 耗时","a":"","d":"把请求按快慢排队，排在第 99% 那个请求花了多久，用来看最慢的那批人体验。","x":"像取快递排队，看最慢那个人等了多久。","c":"研发岗","i":"post-dev"},{"n":"压测","a":"压力测试","d":"人为造大量请求，看系统在高峰期会不会垮。","x":"像故意把水管开到最大，看会不会爆。","c":"研发岗","i":"post-dev"},{"n":"线上事故","a":"","d":"真实用户已经受到影响的那类故障。","x":"像营业中的店突然停电。","c":"研发岗","i":"post-dev"},{"n":"故障复盘","a":"","d":"事故处理完之后，把时间线、原因、责任和改进项理清楚。","x":"像球队赛后一起看录像。","c":"研发岗","i":"post-dev"},{"n":"值班","a":"on-call","d":"轮流盯着线上告警，出问题第一时间响应。","x":"像医院急诊排班，谁值班谁上。","c":"研发岗","i":"post-dev"},{"n":"开关","a":"feature flag","d":"给新功能加一个可以随时开关的阀门，出问题先关掉再说。","x":"像新装的灯先接个独立开关。","c":"研发岗","i":"post-dev"},{"n":"热修复","a":"热修","d":"不等完整发版，直接对线上做小范围修补。","x":"像轮胎漏气先补一贴，回头再换胎。","c":"研发岗","i":"post-dev"},{"n":"接口文档","a":"","d":"写清每个接口收什么、返回什么、出错怎么报，供别人对接。","x":"像电器的接线说明书。","c":"研发岗","i":"post-dev"},{"n":"数据迁移","a":"","d":"把老系统里的数据搬到新系统，还要保证对得上。","x":"像搬家时把东西一件件清点过去。","c":"研发岗","i":"post-dev"},{"n":"兼容性","a":"","d":"新代码要能同时照顾老版本、老数据、老设备。","x":"像新钥匙还得能开老锁。","c":"研发岗","i":"post-dev"},{"n":"兜底方案","a":"兜底","d":"主方案失效时的备用退路，保证不至于彻底不可用。","x":"像电梯停了还有楼梯。","c":"研发岗","i":"post-dev"},{"n":"阻塞","a":"卡住","d":"因为某个问题没解决，整件事停下来推不动。","x":"像下水道堵了，楼上一层都别想用水。","c":"研发岗","i":"post-dev"},{"n":"造数","a":"造数据","d":"人为造一批测试数据，用来验证功能和统计口径。","x":"像演习时用假人代替伤员。","c":"研发岗","i":"post-dev"},{"n":"发布单","a":"","d":"一次上线要填的单子，写清改了什么、怎么回滚、谁批的。","x":"像出车前的行车单。","c":"研发岗","i":"post-dev"},{"n":"视觉稿","a":"UI 稿","d":"界面最终长什么样的图，颜色、字号、间距都定好。","x":"像装修的效果图。","c":"设计岗","i":"post-design"},{"n":"交互稿","a":"交互原型","d":"用户点哪里、跳到哪里、出现什么反馈的那套图。","x":"像说明书里的操作步骤图。","c":"设计岗","i":"post-design"},{"n":"设计规范","a":"","d":"统一颜色、字号、间距、按钮样式的那份标准。","x":"像连锁店的装修手册。","c":"设计岗","i":"post-design"},{"n":"组件库","a":"","d":"把按钮、输入框、弹窗这些常用零件做成一整套可复用素材。","x":"像乐高的标准积木。","c":"设计岗","i":"post-design"},{"n":"栅格","a":"栅格系统","d":"把页面横向切成若干等份，用来对齐所有元素。","x":"像作业本上的方格纸。","c":"设计岗","i":"post-design"},{"n":"留白","a":"呼吸感","d":"故意空出来、不放内容的区域，让页面不挤。","x":"像房间里留出走路的过道。","c":"设计岗","i":"post-design"},{"n":"字号层级","a":"","d":"标题、正文、注释用不同大小的字，让人一眼看出主次。","x":"像报纸上标题大、正文小。","c":"设计岗","i":"post-design"},{"n":"Banner","a":"横幅","d":"页面顶部那条大图，通常放主推活动或产品。","x":"像店门口那条最显眼的横幅。","c":"设计岗","i":"post-design"},{"n":"KV","a":"主视觉","d":"一次活动或产品的主画面，所有物料都从它派生。","x":"像一部电影的海报定妆照。","c":"设计岗","i":"post-design"},{"n":"切图","a":"","d":"把设计稿里要用的图片一块块切出来，交给开发。","x":"像把整张布按纸样裁成片。","c":"设计岗","i":"post-design"},{"n":"标注","a":"设计标注","d":"在设计稿上标出尺寸、颜色值、间距，开发照着写。","x":"像装修图上的尺寸标注。","c":"设计岗","i":"post-design"},{"n":"走查","a":"设计走查","d":"开发做完之后，设计逐个界面对着稿子看有没有偏。","x":"像验收时拿样板一件件对。","c":"设计岗","i":"post-design"},{"n":"还原度","a":"","d":"做出来的界面和设计稿有多接近。","x":"像照着菜谱做出来的菜像不像原版。","c":"设计岗","i":"post-design"},{"n":"可用性","a":"","d":"这东西好不好用，用户能不能顺畅完成目标。","x":"像门把手装在顺手的那一侧。","c":"设计岗","i":"post-design"},{"n":"对比度","a":"","d":"文字和背景的明暗差别，太低就看不清。","x":"像在雾天看远处的路牌。","c":"设计岗","i":"post-design"},{"n":"品牌色","a":"","d":"代表品牌的那一两个固定颜色，所有物料都用它。","x":"像球队的队服颜色。","c":"设计岗","i":"post-design"},{"n":"插画风","a":"","d":"用插画而不是照片来表达内容的一套视觉风格。","x":"像绘本和实景照片的区别。","c":"设计岗","i":"post-design"},{"n":"图标规范","a":"","d":"图标的线条粗细、圆角、尺寸统一的一套规则。","x":"像一套餐具得是同一系列。","c":"设计岗","i":"post-design"},{"n":"适配","a":"","d":"让界面在不同屏幕、不同系统上都不变形、不错位。","x":"像同一件衣服做成不同尺码。","c":"设计岗","i":"post-design"},{"n":"媒介采买","a":"媒介","d":"花钱去买各个渠道的曝光位，谈价格、排时间。","x":"像在闹市租广告牌。","c":"市场岗","i":"post-mkt"},{"n":"KOL","a":"关键意见领袖","d":"粉丝量大、能带动一批人跟着买的人。","x":"像街口那位说话大家都听的老师傅。","c":"市场岗","i":"post-mkt"},{"n":"种子用户","a":"","d":"最早一批愿意试用、还愿意帮你传播的用户。","x":"像新店开业时那几位熟客。","c":"市场岗","i":"post-mkt"},{"n":"公关稿","a":"新闻稿","d":"写给媒体发布的标准稿件，用于对外统一发声。","x":"像公司对外的一张正式名片。","c":"市场岗","i":"post-mkt"},{"n":"品牌联名","a":"联名","d":"两个品牌一起出产品或活动，互相借对方的客群。","x":"像两家店合伙出一款限定套餐。","c":"市场岗","i":"post-mkt"},{"n":"Slogan","a":"广告语","d":"一句短到能记住、又能说清卖点的话。","x":"像招牌上那行大字。","c":"市场岗","i":"post-mkt"},{"n":"视觉锤","a":"","d":"反复出现、让人一看就认出来的固定视觉元素。","x":"像老字号那块特有的招牌形状。","c":"市场岗","i":"post-mkt"},{"n":"搜索指数","a":"","d":"某段时间里有多少人在搜这个词，用来判断热度。","x":"像看最近多少人打听某样东西。","c":"市场岗","i":"post-mkt"},{"n":"话题标签","a":"Hashtag","d":"给内容挂上一个统一标签，方便聚在一起被看到。","x":"像给一堆文件贴上同一个便签。","c":"市场岗","i":"post-mkt"},{"n":"种草笔记","a":"种草","d":"以真实体验口吻写的内容，让人产生想买的念头。","x":"像邻居跟你说她家那口锅特别好用。","c":"市场岗","i":"post-mkt"},{"n":"信息流广告","a":"信息流","d":"混在内容列表里、往下刷时顺带看到的广告。","x":"像报纸正文中间夹着的那块广告。","c":"市场岗","i":"post-mkt"},{"n":"开屏广告","a":"开屏","d":"打开 App 时先占满一屏的那几秒广告。","x":"像进门前先看到的那块巨幅海报。","c":"市场岗","i":"post-mkt"},{"n":"达人 brief","a":"投放 brief","d":"给达人写的要求：讲什么、怎么讲、不能说什么。","x":"像给演员的剧本和角色说明。","c":"市场岗","i":"post-mkt"},{"n":"舆情","a":"","d":"网上关于你品牌的讨论和情绪走向，好的坏的都算。","x":"像街坊邻居最近怎么议论你家店。","c":"市场岗","i":"post-mkt"},{"n":"品牌声量","a":"","d":"一段时间里提到你品牌的总次数和热度。","x":"像这条街上多少人会提起你的店名。","c":"市场岗","i":"post-mkt"},{"n":"广告位","a":"","d":"页面上或视频里可以卖出去放广告的位置。","x":"像商场里可以出租的铺面。","c":"市场岗","i":"post-mkt"},{"n":"投放计划","a":"","d":"写清投哪些渠道、投多少钱、投多久、怎么评估。","x":"像出门旅行的行程表。","c":"市场岗","i":"post-mkt"},{"n":"素材疲劳","a":"","d":"同一套广告素材反复投，看到的人烦了，效果越来越差。","x":"像同一首歌单曲循环一天，再好听也腻。","c":"市场岗","i":"post-mkt"},{"n":"人群包","a":"","d":"按年龄、地域、兴趣等条件圈出来的一批人，用来定向投放。","x":"像按条件筛出来的一份名单。","c":"市场岗","i":"post-mkt"},{"n":"定向","a":"人群定向","d":"规定这条广告只给哪一类人看。","x":"像发传单只发给会买的人。","c":"市场岗","i":"post-mkt"},{"n":"线索","a":"leads","d":"可能有意向、但还没接触过的潜在客户信息。","x":"像还没打过电话的意向名单。","c":"销售岗","i":"post-sales"},{"n":"商机","a":"","d":"已经聊过、确认有需求也有预算的机会。","x":"像已经进门坐下、开始看菜单的客人。","c":"销售岗","i":"post-sales"},{"n":"成单率","a":"成交率","d":"跟进的客户里最后签下来的比例。","x":"像接待十桌客人，有几桌真的点了菜。","c":"销售岗","i":"post-sales"},{"n":"回款","a":"","d":"货或服务已经交付，钱真正到账。","x":"像账上记着收入，但得等钱进兜。","c":"销售岗","i":"post-sales"},{"n":"报价","a":"报价单","d":"给客户的正式价格清单，含配置、数量、有效期。","x":"像装修公司给的那张预算表。","c":"销售岗","i":"post-sales"},{"n":"折扣审批","a":"","d":"要给客户降价，得按权限一层层批。","x":"像商店打折要店长签字。","c":"销售岗","i":"post-sales"},{"n":"续约","a":"续费","d":"合同到期前让客户继续签下一期。","x":"像房租到期接着租。","c":"销售岗","i":"post-sales"},{"n":"客情","a":"客情维护","d":"和客户维持关系的日常功夫：问候、拜访、帮忙。","x":"像和老主顾之间的人情往来。","c":"销售岗","i":"post-sales"},{"n":"拜访","a":"","d":"上门或当面见客户，谈需求也谈关系。","x":"像亲自上门送货顺便聊聊。","c":"销售岗","i":"post-sales"},{"n":"异议处理","a":"","d":"客户提出疑虑或反对意见时，怎么解释和化解。","x":"像顾客嫌贵时你怎么接话。","c":"销售岗","i":"post-sales"},{"n":"逼单","a":"促单","d":"用限时优惠或名额压力，推动客户当场做决定。","x":"像快收摊时喊最后三斤便宜卖。","c":"销售岗","i":"post-sales"},{"n":"转介绍","a":"","d":"老客户把朋友介绍过来，成本最低的一种获客。","x":"像熟客带朋友一起来吃。","c":"销售岗","i":"post-sales"},{"n":"渠道商","a":"代理","d":"帮你卖货的中间商，通常有自己的客户资源。","x":"像帮厂家铺货的批发商。","c":"销售岗","i":"post-sales"},{"n":"返点","a":"返佣","d":"成交之后按比例返给渠道或介绍人的钱。","x":"像介绍生意拿的谢礼。","c":"销售岗","i":"post-sales"},{"n":"提成","a":"","d":"销售按业绩拿的那部分收入。","x":"像跑单按件算的钱。","c":"销售岗","i":"post-sales"},{"n":"目标拆解","a":"","d":"把年度目标按月、按人、按产品分下去。","x":"像把一大块蛋糕切成每人一份。","c":"销售岗","i":"post-sales"},{"n":"销售漏斗","a":"漏斗","d":"从线索、商机、报价到成单，每一层剩多少人。","x":"像一层层筛子，看哪层漏得最多。","c":"销售岗","i":"post-sales"},{"n":"CRM","a":"客户关系系统","d":"记录客户信息、跟进记录和成交情况的那套系统。","x":"像一本记得很细的客户通讯录。","c":"销售岗","i":"post-sales"},{"n":"话术","a":"","d":"面对客户时标准的一套说法，新人照着说也不出错。","x":"像背下来的台词。","c":"销售岗","i":"post-sales"},{"n":"签约周期","a":"","d":"从第一次接触到签合同平均要多久。","x":"像看房到交定金一般要几周。","c":"销售岗","i":"post-sales"},{"n":"招聘漏斗","a":"","d":"从投简历、初筛、面试到入职，每一层还剩多少人。","x":"像一层层筛子，看哪一步漏人最多。","c":"人事行政岗","i":"post-hr"},{"n":"面试官","a":"","d":"负责面试打分的内部员工，要经过统一培训口径才一致。","x":"像比赛里负责打分的裁判。","c":"人事行政岗","i":"post-hr"},{"n":"offer","a":"录用通知","d":"正式发给候选人的录用意向书，写清岗位、薪资、入职时间。","x":"像订婚前的正式提亲。","c":"人事行政岗","i":"post-hr"},{"n":"背调","a":"背景调查","d":"入职前核实候选人之前的履历、离职原因和评价。","x":"像租房前问上一个房东这人怎么样。","c":"人事行政岗","i":"post-hr"},{"n":"入职引导","a":"onboarding","d":"新人到岗头几天要做的一串事：账号、培训、介绍、定目标。","x":"像新手机第一次开机的设置向导。","c":"人事行政岗","i":"post-hr"},{"n":"社保公积金","a":"五险一金","d":"公司和个人按比例一起缴的社会保险和住房公积金。","x":"像强制存的一笔共同基金。","c":"人事行政岗","i":"post-hr"},{"n":"考勤","a":"","d":"记录上下班时间、请假、外出的那套数据。","x":"像学校的点名册。","c":"人事行政岗","i":"post-hr"},{"n":"调休","a":"","d":"加班换来的时间，之后可以调换着休掉。","x":"像攒下的假期零钱，以后找时间花。","c":"人事行政岗","i":"post-hr"},{"n":"加班费","a":"","d":"超出正常工时按法定倍数另外支付的钱。","x":"像超出套餐的流量单独计费。","c":"人事行政岗","i":"post-hr"},{"n":"裁员补偿","a":"N+1","d":"公司主动解除合同时，按工作年限折算给员工的一笔钱。","x":"像提前退租要按合同赔一笔。","c":"人事行政岗","i":"post-hr"},{"n":"员工关系","a":"ER","d":"处理员工投诉、冲突、纪律和离职这些人和人之间的事。","x":"像家里有人闹别扭，得有人来调解。","c":"人事行政岗","i":"post-hr"},{"n":"组织架构","a":"","d":"公司分成哪些部门、谁向谁汇报的那张图。","x":"像一张家族关系图。","c":"人事行政岗","i":"post-hr"},{"n":"汇报线","a":"","d":"一个岗位往上直接汇报给谁，最多几层到老板。","x":"像公司里的户口本。","c":"人事行政岗","i":"post-hr"},{"n":"晋升答辩","a":"","d":"想升职要当着一群人讲自己的成绩，再被打分。","x":"像毕业答辩。","c":"人事行政岗","i":"post-hr"},{"n":"调薪窗口","a":"","d":"一年中允许统一调整薪资的那几个时间点。","x":"像商店只在固定时候改价签。","c":"人事行政岗","i":"post-hr"},{"n":"编制冻结","a":"HC 冻结","d":"一段时间内不许招新人，先把现有的人用起来。","x":"像车位满了，暂时不再放车进来。","c":"人事行政岗","i":"post-hr"},{"n":"试用期考核","a":"","d":"试用期结束前，评估这人到底适不适合留下。","x":"像新菜试卖的试吃反馈。","c":"人事行政岗","i":"post-hr"},{"n":"内部转岗","a":"","d":"员工换到公司内另一个岗位，不用离职再入职。","x":"像在同一个商场里换一家店上班。","c":"人事行政岗","i":"post-hr"},{"n":"劳动合同续签","a":"","d":"合同到期前决定要不要再签一期、条款怎么改。","x":"像租房到期谈续租。","c":"人事行政岗","i":"post-hr"},{"n":"人事档案","a":"","d":"员工从入职到离职的全部记录材料。","x":"像一本从头到尾的就诊病历。","c":"人事行政岗","i":"post-hr"},{"n":"报销","a":"","d":"员工先垫钱办事，再拿票回来把钱要回去。","x":"像先替公司垫了饭钱，回头对账要回来。","c":"财务岗","i":"post-fin"},{"n":"发票查验","a":"验票","d":"核对一张发票是不是真的、金额和抬头对不对。","x":"像收钱时验一下钞票真假。","c":"财务岗","i":"post-fin"},{"n":"对账","a":"","d":"把自家账上的数和银行、供应商、平台的数一条条核上。","x":"像两家记的账本对一遍，看差在哪。","c":"财务岗","i":"post-fin"},{"n":"月结","a":"结账","d":"每月固定时间把当月账目封账，出报表。","x":"像每个月末把抽屉里的票据清一遍、锁上。","c":"财务岗","i":"post-fin"},{"n":"年审","a":"年度审计","d":"每年请外部机构把整年的账查一遍并出结论。","x":"像每年一次全面体检。","c":"财务岗","i":"post-fin"},{"n":"预算编制","a":"","d":"提前把下一年要花多少、花在哪写清楚并层层审批。","x":"像出门前先算好这趟要带多少钱。","c":"财务岗","i":"post-fin"},{"n":"成本中心","a":"","d":"只花钱不直接赚钱的部门，单独核算花了多少。","x":"像家里专门记账的那本开销本。","c":"财务岗","i":"post-fin"},{"n":"费用率","a":"","d":"某项费用占收入的比例，用来判断花得值不值。","x":"像房租占工资的几成。","c":"财务岗","i":"post-fin"},{"n":"单均成本","a":"","d":"平均每一单要摊多少成本。","x":"像一份外卖摊到多少钱的房租水电。","c":"财务岗","i":"post-fin"},{"n":"毛利额","a":"","d":"收入减掉直接成本之后剩下的钱，是个绝对数。","x":"像卖一件衣服赚的差价总额。","c":"财务岗","i":"post-fin"},{"n":"净利","a":"净利润","d":"所有成本和税都扣完之后真正剩下的钱。","x":"像月底钱包里真正剩下的余额。","c":"财务岗","i":"post-fin"},{"n":"回款率","a":"","d":"应该收的钱里，实际收回来的比例。","x":"像借出去十笔钱，收回来几笔。","c":"财务岗","i":"post-fin"},{"n":"应付账款","a":"应付","d":"已经收到货或服务、但还没付钱给供应商的那部分。","x":"像赊账买的东西，账上记着还没给钱。","c":"财务岗","i":"post-fin"},{"n":"备用金","a":"","d":"先支给某个人或某个部门、用于零星开销的一笔钱。","x":"像家里的零钱罐。","c":"财务岗","i":"post-fin"},{"n":"记账凭证","a":"凭证","d":"每一笔账背后的那张单据，写清谁、什么时候、为什么。","x":"像超市小票，能追溯这笔钱怎么花的。","c":"财务岗","i":"post-fin"},{"n":"折旧","a":"","d":"设备或房子按使用年限，每年摊掉一部分价值。","x":"像新车开一年就掉一部分价。","c":"财务岗","i":"post-fin"},{"n":"汇兑损益","a":"","d":"因为汇率变动，外币资产或负债折算成本币时的盈亏。","x":"像换外币旅游，回来时汇率变了钱就多了或少了。","c":"财务岗","i":"post-fin"},{"n":"应收账款周转","a":"周转天数","d":"从开票到收到钱平均要多少天。","x":"像借出去的钱多久能收回来一轮。","c":"财务岗","i":"post-fin"},{"n":"预提费用","a":"","d":"已经发生但还没收到发票的费用，先按估计记进当月。","x":"像知道这个月水电还没出账，先估个数留出来。","c":"财务岗","i":"post-fin"},{"n":"资金计划","a":"","d":"预测未来几个月钱什么时候进、什么时候出，够不够用。","x":"像看家里的账，算这个月会不会断粮。","c":"财务岗","i":"post-fin"},{"n":"工单","a":"客服工单","d":"用户提出一个问题就生成一条待处理记录，从受理跟到关闭。","x":"像医院挂号后拿到的那张就诊单。","c":"客服岗","i":"post-cs"},{"n":"首次响应时长","a":"首响","d":"用户发来消息到客服第一次回复，中间隔了多久。","x":"像按了呼叫铃，多久有人应。","c":"客服岗","i":"post-cs"},{"n":"解决率","a":"","d":"一批问题里真正被解决掉的比例。","x":"像报修十次，几次真修好了。","c":"客服岗","i":"post-cs"},{"n":"NPS","a":"净推荐值","d":"问用户愿不愿意推荐给别人，用推荐者和贬损者的比例算出一个分数。","x":"像问街坊：你会介绍朋友来这家店吗。","c":"客服岗","i":"post-cs"},{"n":"满意度","a":"CSAT","d":"用户对这次服务打的分。","x":"像吃完饭后在点评上给的星级。","c":"客服岗","i":"post-cs"},{"n":"升级","a":"工单升级","d":"一线解决不了，往上一级或转给专业团队处理。","x":"像普通门诊看不了，转专家号。","c":"客服岗","i":"post-cs"},{"n":"投诉","a":"","d":"用户明确表达不满、要求处理的记录。","x":"像意见本上写满的那一页。","c":"客服岗","i":"post-cs"},{"n":"退款","a":"","d":"把钱退还给用户，走审批和原路退回。","x":"像买了不满意退货拿回钱。","c":"客服岗","i":"post-cs"},{"n":"赔付","a":"","d":"因为己方过错额外补偿给用户的钱或券。","x":"像外卖超时平台补的那张券。","c":"客服岗","i":"post-cs"},{"n":"知识库","a":"FAQ","d":"把常见问题和标准答案整理起来，客服照着查照着答。","x":"像一本翻旧了的答题手册。","c":"客服岗","i":"post-cs"},{"n":"话术库","a":"","d":"各种场景下该怎么说的一整套标准说法。","x":"像演员的台词本。","c":"客服岗","i":"post-cs"},{"n":"质检","a":"服务质检","d":"抽查客服的聊天记录或录音，看有没有违规、态度好不好。","x":"像抽查作业看有没有抄。","c":"客服岗","i":"post-cs"},{"n":"坐席","a":"","d":"一个客服同时能接待的那条线，一个人算一个坐席。","x":"像银行窗口，一个窗口算一个位。","c":"客服岗","i":"post-cs"},{"n":"接通率","a":"","d":"打进来或发过来的请求里，真正被接起来的比例。","x":"像打电话有多少次有人接。","c":"客服岗","i":"post-cs"},{"n":"排队时长","a":"","d":"用户等多久才轮到自己被接待。","x":"像在银行取号后坐着等的时间。","c":"客服岗","i":"post-cs"},{"n":"WBS","a":"工作分解结构","d":"把一个大项目拆成一件件可分配、可验收的小任务。","x":"像把一桌菜拆成一道道工序。","c":"项目管理岗","i":"post-pmgr"},{"n":"甘特图","a":"","d":"把每项任务的起止时间画成横条，一眼看出谁先谁后。","x":"像火车时刻表摊开来看。","c":"项目管理岗","i":"post-pmgr"},{"n":"关键路径","a":"","d":"决定整个项目最短工期的哪一条任务链，这条一拖全都拖。","x":"像一串串联的灯泡，断一个全不亮。","c":"项目管理岗","i":"post-pmgr"},{"n":"资源冲突","a":"","d":"同一个人或同一笔预算被两个任务同时占用。","x":"像一辆车被两家人同时订了。","c":"项目管理岗","i":"post-pmgr"},{"n":"风险登记","a":"风险清单","d":"把可能出问题的事列出来，标概率、影响和应对人。","x":"像出门前看天气预报决定带不带伞。","c":"项目管理岗","i":"post-pmgr"},{"n":"变更单","a":"","d":"项目范围、时间或预算要改，就得填一张单子走审批。","x":"像改合同要签补充协议。","c":"项目管理岗","i":"post-pmgr"},{"n":"交付物","a":"","d":"项目结束时要交出去的具体东西：文档、系统、报告。","x":"像毕业要交的论文和作品。","c":"项目管理岗","i":"post-pmgr"},{"n":"周报","a":"","d":"每周写一次进度、问题、下周计划。","x":"像给家里报个平安，说说这周干了啥。","c":"项目管理岗","i":"post-pmgr"},{"n":"站会","a":"每日站会","d":"每天站着开十几分钟，每人说昨天做了什么、今天做什么、卡在哪。","x":"像球队开赛前碰个头对一下战术。","c":"项目管理岗","i":"post-pmgr"},{"n":"评审会","a":"","d":"把方案或成果摆出来，请相关方一起挑问题、定结论。","x":"像作品展出前请人先看一遍。","c":"项目管理岗","i":"post-pmgr"},{"n":"结项","a":"","d":"项目做完了，做验收、归档、结算、复盘这一套收尾。","x":"像装修完验收、结账、交钥匙。","c":"项目管理岗","i":"post-pmgr"},{"n":"范围基线","a":"基线","d":"一开始谈定的范围，之后改动都要和它对比。","x":"像量身高时墙上画的那道线。","c":"项目管理岗","i":"post-pmgr"},{"n":"依赖方","a":"","d":"这件事必须等对方先交付才能继续的那一方。","x":"像等上游放水，下游才能开闸。","c":"项目管理岗","i":"post-pmgr"},{"n":"拍板","a":"","d":"有决策权的人当场定下来，不再拖。","x":"像一桌人点菜犹豫，最后有人说就这几个。","c":"项目管理岗","i":"post-pmgr"},{"n":"双周迭代","a":"","d":"两周一个循环：定需求、开发、验收、发布。","x":"像两周一次的轮班。","c":"项目管理岗","i":"post-pmgr"},{"n":"里程碑计划","a":"","d":"把项目拆成几个关键时间点，每个点必须有明确产出。","x":"像长跑路上的公里牌。","c":"项目管理岗","i":"post-pmgr"},{"n":"项目章程","a":"","d":"项目启动时定的那份文件：目标、范围、负责人、资源。","x":"像开店前签的那份合伙协议。","c":"项目管理岗","i":"post-pmgr"},{"n":"干系人会议","a":"","d":"把会被影响、能影响项目的人叫到一起对齐。","x":"像装修前把邻居和物业都叫来打个招呼。","c":"项目管理岗","i":"post-pmgr"},{"n":"进度偏差","a":"","d":"实际进度和计划进度之间差了多少。","x":"像导航说十分钟到，实际走了二十分钟。","c":"项目管理岗","i":"post-pmgr"},{"n":"验收会","a":"","d":"把成果摆出来，请需求方逐条确认可以接收。","x":"像交房时一起验房签字。","c":"项目管理岗","i":"post-pmgr"},{"n":"变量","a":"variable","d":"给一块数据起的名字，程序后面靠这个名字反复取用这块数据。","x":"像给抽屉贴标签，写「袜子」就知道里面放什么。","c":"研发岗","i":"post-dev"},{"n":"常量","a":"constant","d":"一旦设定就不能再改的值，用来放那些本来就不该变的东西。","x":"像刻在石头上的门牌号。","c":"研发岗","i":"post-dev"},{"n":"作用域","a":"scope","d":"一个名字在代码的哪一段范围内有效，出了这段就失效。","x":"像房间里的灯，只照这一间。","c":"研发岗","i":"post-dev"},{"n":"闭包","a":"closure","d":"函数把外面的变量一起打包带走，之后单独用也能记得那个值。","x":"像出门时顺手把家里的钥匙装进包里。","c":"研发岗","i":"post-dev"},{"n":"递归","a":"recursion","d":"一个函数在自己内部又调用自己，一层层往下处理。","x":"像两面镜子对照，影像一层套一层。","c":"研发岗","i":"post-dev"},{"n":"遍历","a":"iterate","d":"按顺序把一组数据一条条处理一遍。","x":"像挨个翻抽屉找那张发票。","c":"研发岗","i":"post-dev"},{"n":"泛型","a":"generics","d":"写一份代码能适配多种数据类型，用的时候再指定具体是哪一种。","x":"像同一款鞋盒能装不同尺码的鞋。","c":"研发岗","i":"post-dev"},{"n":"抽象类","a":"","d":"只写公共部分、不能直接拿来用的父类，具体要靠子类补完。","x":"像只画了轮廓的底稿，颜色得后面填。","c":"研发岗","i":"post-dev"},{"n":"继承","a":"","d":"子类直接拿到父类已有的能力，再补自己的。","x":"像孩子天生随了父母的某些特征。","c":"研发岗","i":"post-dev"},{"n":"多态","a":"","d":"同一个动作，不同类型的东西各按自己的方式做。","x":"像「打开」这个词，开门和开瓶盖动作完全不同。","c":"研发岗","i":"post-dev"},{"n":"方法重载","a":"函数重载","d":"同名函数可以有好几版，靠参数个数或类型区分用哪一版。","x":"像「来一杯」在奶茶店和咖啡店各做各的。","c":"研发岗","i":"post-dev"},{"n":"命名空间","a":"namespace","d":"给一批名字套上统一前缀，避免和别处的同名撞车。","x":"像同一栋楼里用几单元几号区分。","c":"研发岗","i":"post-dev"},{"n":"正则表达式","a":"regex","d":"用一小串符号描述「什么样的文本算匹配」，用来查找、校验、替换。","x":"像用一张带通配符的表格去找符合条件的号。","c":"研发岗","i":"post-dev"},{"n":"类型转换","a":"","d":"把一种数据类型变成另一种，比如把文本「123」变成数字 123。","x":"像把一袋米称重后写成数字。","c":"研发岗","i":"post-dev"},{"n":"空指针","a":"null 引用","d":"本该有东西的地方是空的，程序一用就崩。","x":"像按约定去 3 号柜取货，柜子是空的。","c":"研发岗","i":"post-dev"},{"n":"内存泄漏","a":"","d":"用过的内存没还回去，越攒越多，最后卡死。","x":"像借的书一直不还，书架迟早被占满。","c":"研发岗","i":"post-dev"},{"n":"垃圾回收","a":"GC","d":"系统自动找出不再使用的内存并收回去。","x":"像定期有人来收走堆在楼道的旧家具。","c":"研发岗","i":"post-dev"},{"n":"不可变对象","a":"","d":"创建之后内容再也不许改的对象，要改就造一个新的。","x":"像打印出来的发票，要改只能重开一张。","c":"研发岗","i":"post-dev"},{"n":"纯函数","a":"","d":"只根据输入算结果、不碰外部状态、同样输入永远同样输出的函数。","x":"像自动售货机，投一样的钱出一样的东西。","c":"研发岗","i":"post-dev"},{"n":"柯里化","a":"","d":"把「要几个参数的函数」拆成一串「每次只收一个参数」的函数。","x":"像分期付款，一次付一部分。","c":"研发岗","i":"post-dev"},{"n":"惰性求值","a":"","d":"先不算，等到真用上那一刻才算。","x":"像点外卖到店才现做，不提前炒好放着。","c":"研发岗","i":"post-dev"},{"n":"语法糖","a":"","d":"让代码写起来更短的简写形式，本质和啰嗦写法一样。","x":"像「十分钟后到」替代一长串时间说明。","c":"研发岗","i":"post-dev"},{"n":"宏","a":"","d":"一段在编译前就被替换展开的代码模板。","x":"像文档里的自动替换：见到「甲方」就填成公司名。","c":"研发岗","i":"post-dev"},{"n":"预处理器","a":"","d":"真正编译之前先跑一遍的环节，用条件决定哪些代码参与编译。","x":"像印刷前先按需删掉不适用的章节。","c":"研发岗","i":"post-dev"},{"n":"指针","a":"","d":"存的是「东西放在哪」的地址，而不是东西本身。","x":"像写着门牌号的纸条，不是房子。","c":"研发岗","i":"post-dev"},{"n":"值传递","a":"","d":"调用时把数据复制一份给函数，函数改的是副本。","x":"像把文件复印一份给对方，他改复印件。","c":"研发岗","i":"post-dev"},{"n":"引用传递","a":"","d":"调用时把数据的地址给函数，函数改的就是原件。","x":"像把家门钥匙给对方，他进去动的是你的东西。","c":"研发岗","i":"post-dev"},{"n":"栈溢出","a":"stack overflow","d":"函数一层层调用太多、把调用栈撑爆了，程序直接退出。","x":"像一摞碗叠太高，最后塌了。","c":"研发岗","i":"post-dev"},{"n":"缓冲区","a":"buffer","d":"数据先临时堆在这里，攒够一批或等对方准备好再处理。","x":"像超市收银台前排队的那段通道。","c":"研发岗","i":"post-dev"},{"n":"位运算","a":"","d":"直接对数字的二进制位做与、或、移位这类操作，快但不好读。","x":"像直接拨开关的每一格，而不是说「调到第 5 档」。","c":"研发岗","i":"post-dev"},{"n":"浮点精度","a":"","d":"小数在计算机里存不精确，0.1+0.2 可能不等于 0.3。","x":"像用一把最小刻度是厘米的尺，量不出毫米。","c":"研发岗","i":"post-dev"},{"n":"异常捕获","a":"try-catch","d":"把可能出错的代码包起来，出错时接住错误、不让整个程序崩。","x":"像在楼下铺张气垫，人掉下来不至于摔死。","c":"研发岗","i":"post-dev"},{"n":"日志级别","a":"","d":"给日志分等级：调试、信息、警告、错误，用来控制打多细。","x":"像医院的轻诊、急诊、抢救分级。","c":"研发岗","i":"post-dev"},{"n":"事件冒泡","a":"","d":"点了一个小元素，事件会一层层往上传给它的外层容器。","x":"像在公司里反馈问题，先找组长再往上报。","c":"研发岗","i":"post-dev"},{"n":"事件循环","a":"event loop","d":"程序用一个循环不停取出待办任务来执行，避免互相卡住。","x":"像银行只开一个窗口，按号一个个叫。","c":"研发岗","i":"post-dev"},{"n":"虚拟 DOM","a":"","d":"先在内存里算好界面该怎么变，只把真正变化的部分同步到屏幕上。","x":"像装修前先在纸上改图纸，改定了再动墙。","c":"研发岗","i":"post-dev"},{"n":"tree-shaking","a":"摇树优化","d":"打包时把没用到的代码剪掉，让文件变小。","x":"像搬家时把用不上的东西扔掉再装车。","c":"研发岗","i":"post-dev"},{"n":"polyfill","a":"垫片","d":"给老浏览器补一段代码，让它也能用新语法。","x":"像给老房子加装扶手，适应新的无障碍标准。","c":"研发岗","i":"post-dev"},{"n":"跨域","a":"CORS 限制","d":"浏览器默认不许一个网站去读另一个网站的接口数据，需要对方明确放行。","x":"像小区门禁，外人不打招呼进不来。","c":"研发岗","i":"post-dev"},{"n":"本地存储","a":"LocalStorage","d":"把少量数据存在用户自己的浏览器里，关掉页面也还在。","x":"像把便签贴在自己桌上，别人看不见。","c":"研发岗","i":"post-dev"},{"n":"组件生命周期","a":"","d":"一个界面组件从创建、挂载、更新到销毁的几个固定阶段。","x":"像一间店铺的装修、开业、翻新、关门。","c":"研发岗","i":"post-dev"},{"n":"props","a":"属性传参","d":"父组件把数据传给子组件的那一份参数。","x":"像点菜时说清「不要辣、少盐」。","c":"研发岗","i":"post-dev"},{"n":"hooks","a":"钩子函数","d":"在组件特定时机被自动调用的一小段逻辑。","x":"像电梯到楼层自动开门。","c":"研发岗","i":"post-dev"},{"n":"防抖","a":"debounce","d":"连续触发时只认最后一次，停手一段时间后才真正执行。","x":"像电梯门，一直有人进出就一直不合。","c":"研发岗","i":"post-dev"},{"n":"节流","a":"throttle","d":"不管触发多频繁，固定间隔内最多执行一次。","x":"像地铁限流，每隔几分钟放一批人进站。","c":"研发岗","i":"post-dev"},{"n":"懒加载","a":"","d":"先不加载，等真的滚到或点到时才去取。","x":"像自助餐现取现吃，不提前摆满一桌。","c":"研发岗","i":"post-dev"},{"n":"骨架屏","a":"","d":"内容还没到，先显示灰块占位，让页面看起来在加载。","x":"像相框先挂上，照片后装。","c":"研发岗","i":"post-dev"},{"n":"gRPC","a":"","d":"一种让两个服务互相调用的通信方式，比普通 HTTP 传输更紧凑、更快。","x":"像两家公司之间走专用货运通道，不走普通快递。","c":"研发岗","i":"post-dev"},{"n":"RPC","a":"远程过程调用","d":"调用另一台机器上的函数，写起来像调本地的。","x":"像打内线电话让隔壁部门帮你盖章。","c":"研发岗","i":"post-dev"},{"n":"事务隔离级别","a":"","d":"规定两个同时进行的事务之间能看到对方多少中间状态，级别越高越安全也越慢。","x":"像两个人同时改一份文档，先锁起来还是允许各改各的。","c":"研发岗","i":"post-dev"},{"n":"分布式锁","a":"","d":"多个服务抢同一份资源时，用一个公共标记保证同一时刻只有一个在动。","x":"像公共厕所门上的那块「有人」牌子。","c":"研发岗","i":"post-dev"},{"n":"死信队列","a":"","d":"反复处理失败的消息被挪到另一个队列，等人来查，不堵住主流程。","x":"像快递反复投递失败的包裹先放回仓库待处理。","c":"研发岗","i":"post-dev"},{"n":"令牌桶","a":"token bucket","d":"按固定速度往桶里放令牌，请求要拿令牌才能通过，用来限速。","x":"像景区按分钟发票，拿到票才能进。","c":"研发岗","i":"post-dev"},{"n":"漏桶算法","a":"","d":"请求先进桶，桶底按固定速度漏出，漏不完就排队或丢弃。","x":"像洗手池下水口固定流速，倒太快就积起来。","c":"研发岗","i":"post-dev"},{"n":"一致性哈希","a":"","d":"分片时用同一种算法算位置，加减机器只影响一小部分数据。","x":"像按门牌号分区送信，多一个邮差只调整几条街。","c":"研发岗","i":"post-dev"},{"n":"主从复制","a":"","d":"一台主库负责写，几台从库跟着同步，读请求分给从库。","x":"像一个人记账，几个人抄副本供查阅。","c":"研发岗","i":"post-dev"},{"n":"CAP","a":"一致性可用性分区容错","d":"分布式系统里，一致性、可用性、分区容错三者最多同时满足两个。","x":"像三个人分一块饼，怎么切都有人少一口。","c":"研发岗","i":"post-dev"},{"n":"最终一致性","a":"","d":"不要求一改完所有地方立刻看到，但过一会儿一定会一致。","x":"像转账，短信到账和余额更新可能差几秒。","c":"研发岗","i":"post-dev"},{"n":"缓存穿透","a":"","d":"查一个根本不存在的数据，每次都绕过缓存打到数据库。","x":"像每次都问前台「有没有我的快递」，其实根本没寄。","c":"研发岗","i":"post-dev"},{"n":"布隆过滤器","a":"","d":"用很小的空间快速判断「这东西一定没有」或「可能有」。","x":"像门口保安扫一眼名单，先挡掉肯定不在的人。","c":"研发岗","i":"post-dev"},{"n":"健康检查","a":"health check","d":"系统定期问每个服务「你还活着吗」，不回应就摘掉流量。","x":"像上班打卡，连续没打卡就当缺勤。","c":"研发岗","i":"post-dev"},{"n":"优雅停机","a":"","d":"关服务前先停止接新请求，把手上的活干完再退出。","x":"像打烊前先不让人进，等店里客人吃完再锁门。","c":"研发岗","i":"post-dev"},{"n":"应急预案","a":"降级预案","d":"出故障时按事先写好的步骤处置，先保核心功能。","x":"像商场的消防疏散图，贴在墙上平时不看。","c":"研发岗","i":"post-dev"},{"n":"数组","a":"array","d":"一排连续的格子，按编号直接取，找第几个都很快。","x":"像电影院的连座，按排号直接坐下。","c":"研发岗","i":"post-dev"},{"n":"链表","a":"","d":"每个元素都记着下一个在哪，插入删除方便但找起来要一个个走。","x":"像寻宝纸条，每张写着下一张藏哪。","c":"研发岗","i":"post-dev"},{"n":"栈","a":"stack","d":"后放的先取，只能从一头进出。","x":"像一摞盘子，只能从最上面拿。","c":"研发岗","i":"post-dev"},{"n":"队列","a":"queue","d":"先排队的先处理，一头进一头出。","x":"像奶茶店排号，先来的先做。","c":"研发岗","i":"post-dev"},{"n":"哈希表","a":"散列表","d":"把键算成一个位置直接跳过去找值，理想情况一次就中。","x":"像按姓氏笔画把档案分抽屉，找起来不用翻全部。","c":"研发岗","i":"post-dev"},{"n":"二叉树","a":"","d":"每个节点最多分两个叉的结构，用来快速查找和排序。","x":"像层层分组的选择题，每次二选一缩小范围。","c":"研发岗","i":"post-dev"},{"n":"时间复杂度","a":"","d":"描述数据量变大时，耗时增长得有多快。","x":"像说「人翻倍，活也翻倍」还是「人翻倍，活翻四倍」。","c":"研发岗","i":"post-dev"},{"n":"空间复杂度","a":"","d":"描述数据量变大时，额外占用的内存增长得有多快。","x":"像问这活儿得多大的仓库才放得下。","c":"研发岗","i":"post-dev"},{"n":"二分查找","a":"","d":"每次砍掉一半范围去找目标，前提是数据已经排好序。","x":"像猜数字时先问「大于 50 吗」，一路砍半。","c":"研发岗","i":"post-dev"},{"n":"linter","a":"代码检查工具","d":"自动检查代码里写法问题、潜在 bug 和风格不一致。","x":"像交卷前有人帮你检查错别字和格式。","c":"研发岗","i":"post-dev"},{"n":"formatter","a":"格式化工具","d":"自动把缩进、空格、换行调成统一风格，不改逻辑。","x":"像自动排版，把手写稿变成规整的印刷体。","c":"研发岗","i":"post-dev"},{"n":"断点","a":"breakpoint","d":"在代码某一行做个标记，运行到这儿就暂停，好让你看当时的值。","x":"像看电影按暂停，看清这一帧画面。","c":"研发岗","i":"post-dev"},{"n":"调用栈","a":"call stack","d":"出问题时能看到「谁调了谁」的那一串层级。","x":"像追溯一通电话转了几道手。","c":"研发岗","i":"post-dev"},{"n":"错误堆栈","a":"报错栈","d":"报错时打印出来的一长串位置信息，从出错点一路往外列。","x":"像快递异常单上写的完整转运路径。","c":"研发岗","i":"post-dev"},{"n":".env 文件","a":"环境变量文件","d":"把密钥、地址这类配置写在文件里，不硬编码进代码。","x":"像出门前把钥匙钱包单独放一个口袋。","c":"研发岗","i":"post-dev"},{"n":"Makefile","a":"","d":"把常用命令写成一份清单，敲一个词就执行一串。","x":"像微波炉上的「一键加热」按钮。","c":"研发岗","i":"post-dev"},{"n":"shell 脚本","a":"","d":"把一串命令行操作写进文件，一次跑完。","x":"像把一套操作步骤录成宏。","c":"研发岗","i":"post-dev"},{"n":"cron","a":"定时任务表达式","d":"用五个字段描述「什么时候执行」，比如每天凌晨三点。","x":"像闹钟设定：每周一到周五七点响。","c":"研发岗","i":"post-dev"},{"n":"systemd","a":"","d":"Linux 上管理后台服务的系统，负责开机自启、崩溃重启。","x":"像公司的值班室，谁该上班、谁倒下了都归它管。","c":"研发岗","i":"post-dev"},{"n":"grep","a":"","d":"在文件或输出里按关键词搜索，只留下匹配的行。","x":"像用荧光笔在长文档里划出所有含某个词的行。","c":"研发岗","i":"post-dev"},{"n":"curl","a":"","d":"命令行里直接发 HTTP 请求的小工具，用来测接口。","x":"像不带界面、直接敲门问一句「在吗」。","c":"研发岗","i":"post-dev"},{"n":"tar","a":"打包压缩","d":"把一堆文件打成一个包，方便传输和备份。","x":"像把散装行李装进一个箱子再托运。","c":"研发岗","i":"post-dev"},{"n":"chmod","a":"改权限","d":"改一个文件谁能读、谁能写、谁能执行。","x":"像给抽屉换锁，规定谁有钥匙。","c":"研发岗","i":"post-dev"},{"n":"虚拟环境","a":"venv","d":"给每个项目单独一套依赖，互不干扰。","x":"像每道菜用自己那口锅，不串味。","c":"研发岗","i":"post-dev"},{"n":"pip","a":"","d":"Python 的包管理工具，用来装、升、卸第三方库。","x":"像手机应用商店，缺什么装什么。","c":"研发岗","i":"post-dev"},{"n":"Dockerfile","a":"","d":"写清怎么把程序打包成镜像的那份说明书。","x":"像一份标准菜谱，照着做出来的每份都一样。","c":"研发岗","i":"post-dev"},{"n":"docker-compose","a":"","d":"用一份配置文件一次起多个容器，并规定它们怎么连。","x":"像宴席的总菜单，几道菜一起排好上桌顺序。","c":"研发岗","i":"post-dev"},{"n":"kubectl","a":"","d":"操作 Kubernetes 集群的命令行工具。","x":"像遥控器，隔着屏幕指挥一堆机器。","c":"研发岗","i":"post-dev"},{"n":"Pod","a":"","d":"Kubernetes 里最小的一调度单位，通常装一个应用实例。","x":"像集装箱，最小的一整箱。","c":"研发岗","i":"post-dev"},{"n":"Deployment","a":"","d":"声明「我要几个副本、用哪个镜像」，系统负责维持这个数量。","x":"像排班表上写「这个岗位常备三人」，缺了自动补。","c":"研发岗","i":"post-dev"},{"n":"helm","a":"","d":"Kubernetes 的包管理工具，用模板一次装好一整套服务。","x":"像装修套餐，一次把水电家具都配齐。","c":"研发岗","i":"post-dev"},{"n":"脚手架","a":"scaffold","d":"一条命令生成项目的基础结构，省得从空目录搭起。","x":"像盖房先立好框架，再往里填。","c":"研发岗","i":"post-dev"},{"n":"CRUD","a":"增删改查","d":"新建、查询、修改、删除这四类最基本的操作。","x":"像账本的记一笔、翻一页、改一行、划掉一行。","c":"研发岗","i":"post-dev"},{"n":"DTO","a":"数据传输对象","d":"专门用来在层与层之间搬数据的那个结构，不带业务逻辑。","x":"像搬家用的纸箱，只负责装和运。","c":"研发岗","i":"post-dev"},{"n":"DAO","a":"数据访问对象","d":"把所有直接读写数据库的代码收在一起的那一层。","x":"像仓库管理员，进出货都找他。","c":"研发岗","i":"post-dev"},{"n":"Controller","a":"控制器","d":"接住外部请求、决定交给谁处理的那一层。","x":"像前台接待，先问清来意再分派。","c":"研发岗","i":"post-dev"},{"n":"Service 层","a":"业务层","d":"真正写业务规则的地方，不直接管界面也不直接管数据库。","x":"像后厨，按菜谱决定怎么做。","c":"研发岗","i":"post-dev"},{"n":"定时任务","a":"","d":"按设定时间自动跑的任务，比如每天凌晨清算。","x":"像家里的净水器定时冲洗。","c":"研发岗","i":"post-dev"},{"n":"软删除","a":"","d":"不真删数据，只打个「已删除」标记，界面上不展示。","x":"像把文件移进回收站，还没真清空。","c":"研发岗","i":"post-dev"},{"n":"状态机","a":"","d":"把一件事拆成几个状态和允许的跳转，只能按规则走。","x":"像订单只能从待付款走到已付款，不能跳回去。","c":"研发岗","i":"post-dev"},{"n":"事件驱动","a":"","d":"不按顺序一步步调，而是谁发生了什么事就通知关心它的人。","x":"像小区群里喊一声「快递到了」，需要的人自己下楼。","c":"研发岗","i":"post-dev"},{"n":"生产者消费者","a":"","d":"一方负责往队列里放任务，另一方按自己节奏取走处理。","x":"像传菜口：后厨放，服务员取，谁快谁慢都不堵。","c":"研发岗","i":"post-dev"},{"n":"背压","a":"backpressure","d":"下游处理不过来时，反过来让上游放慢速度。","x":"像水管下游堵了，上游的水泵自动降速。","c":"研发岗","i":"post-dev"},{"n":"批处理","a":"","d":"攒一批一起处理，而不是一条一条来。","x":"像攒够一筐衣服再开洗衣机。","c":"研发岗","i":"post-dev"},{"n":"增量更新","a":"","d":"只处理发生变化的那部分，不动没变的。","x":"像只补墙上有裂缝的那一块，不整面重刷。","c":"研发岗","i":"post-dev"},{"n":"数据校验","a":"","d":"数据进系统前先按规则检查一遍，不合格就拒掉。","x":"像进门前先查证件，不合格不放行。","c":"研发岗","i":"post-dev"},{"n":"脱敏","a":"","d":"把手机号、身份证这类敏感信息遮掉一部分再展示或存储。","x":"像把账单上的卡号盖住后四位。","c":"研发岗","i":"post-dev"},{"n":"接口字段","a":"","d":"接口里一个个具体的数据项，比如用户 id、订单号、金额。","x":"像快递单上的每一格：收件人、电话、地址。","c":"产品岗","i":"post-pm"},{"n":"请求参数","a":"","d":"调接口时要传进去的条件，缺一个可能就查不到或报错。","x":"像填表时那些必填项。","c":"产品岗","i":"post-pm"},{"n":"返回值","a":"响应体","d":"接口处理完回给你的那份数据。","x":"像柜台办完事递回来的单据。","c":"产品岗","i":"post-pm"},{"n":"状态码","a":"","d":"用数字表示这次请求的结果，200 是成功，4xx 是你这边有问题，5xx 是对方出错。","x":"像办事窗口给的排队小票上的编号。","c":"产品岗","i":"post-pm"},{"n":"错误码","a":"","d":"业务自己定义的失败编号，用来说明具体是哪种失败。","x":"像医院检查单上的异常项标号。","c":"产品岗","i":"post-pm"},{"n":"数据库表","a":"","d":"数据存进去的那张二维表，一行是一条记录，一列是一个属性。","x":"像一张 Excel 清单。","c":"产品岗","i":"post-pm"},{"n":"字段类型","a":"","d":"这一列存的是数字、文字还是时间，定错了会存不进去或算错。","x":"像表格里那一格规定只能填日期。","c":"产品岗","i":"post-pm"},{"n":"唯一键","a":"","d":"规定这一列的值不能重复，比如手机号、订单号。","x":"像身份证号，一个人只能有一个。","c":"产品岗","i":"post-pm"},{"n":"关联表","a":"","d":"两张表靠一个共同字段连起来，用来把分散的信息拼在一起。","x":"像用同一个订单号把付款记录和物流记录对上。","c":"产品岗","i":"post-pm"},{"n":"接口对齐","a":"","d":"产品和研发把字段名、含义、取值范围一条条对清楚。","x":"像两个人核对清单，逐项确认写的是不是一回事。","c":"产品岗","i":"post-pm"},{"n":"默认值","a":"","d":"用户没填时系统自动用的那个值。","x":"像表格里预先印好的「男/女」勾选项。","c":"产品岗","i":"post-pm"},{"n":"埋点事件","a":"","d":"用户在页面上做的一个具体动作，比如点击、提交、曝光。","x":"像在门口装个计数器，进一个记一个。","c":"产品岗","i":"post-pm"},{"n":"事件属性","a":"","d":"描述这个动作的附加信息，比如从哪个页面点、点了哪个按钮。","x":"像记账时顺手写上用途和地点。","c":"产品岗","i":"post-pm"},{"n":"埋点验证","a":"","d":"上线前确认埋点真的发出去了、字段也没错。","x":"像开业前先试按一遍呼叫铃，确认响。","c":"产品岗","i":"post-pm"},{"n":"报表口径","a":"","d":"一张报表里每个数字是怎么算出来的那套定义。","x":"像菜谱写清一勺是多少克，不然十个人做出十个味。","c":"产品岗","i":"post-pm"},{"n":"指标口径","a":"","d":"一个指标到底怎么统计：算不算退款、算不算重复用户。","x":"像量身高是穿鞋量还是光脚量，得先说清。","c":"产品岗","i":"post-pm"},{"n":"口径对齐","a":"","d":"几个部门把同一个指标的定义谈到一致，避免各报各的数。","x":"像几个人对表，先把时间调成一样的。","c":"产品岗","i":"post-pm"},{"n":"数据字典","a":"","d":"把系统里所有字段的名称、含义、取值范围整理成一本册子。","x":"像一本术语对照表。","c":"产品岗","i":"post-pm"},{"n":"指标树","a":"","d":"把核心指标一层层拆成若干子指标，看清每个数受什么影响。","x":"像把「营业额」拆成客流乘客单价再继续拆。","c":"产品岗","i":"post-pm"},{"n":"维度","a":"dimension","d":"看数据的角度，比如按天、按渠道、按城市。","x":"像同一笔账可以按月份看，也可以按门店看。","c":"产品岗","i":"post-pm"},{"n":"度量","a":"measure","d":"被统计的那个数值本身，比如人数、金额、次数。","x":"像报表里真正被加总的那些数字。","c":"产品岗","i":"post-pm"},{"n":"宽表","a":"","d":"把很多张表的信息提前拼成一张大表，查起来快但占空间。","x":"像把各处信息汇总到一张总表上。","c":"产品岗","i":"post-pm"},{"n":"实时数仓","a":"","d":"数据一产生就进仓、几分钟内能查，而不是等第二天。","x":"像现做的快餐，不是隔夜菜。","c":"产品岗","i":"post-pm"},{"n":"离线报表","a":"","d":"每天固定时间跑一次、第二天才看得到的报表。","x":"像每天早上送来的日报。","c":"产品岗","i":"post-pm"},{"n":"自助查询","a":"","d":"业务同学自己写条件查数，不用每次都找数据同学排队。","x":"像自助取号机，不用去柜台问。","c":"产品岗","i":"post-pm"},{"n":"SQL 查询","a":"","d":"用一句结构化的话去数据库里取数，比如「取上个月北京的全部订单」。","x":"像给仓库管理员一张写清条件的提货单。","c":"产品岗","i":"post-pm"},{"n":"关联查询","a":"","d":"一次同时查几张表，靠共同字段把结果拼起来。","x":"像把订单表和用户表按 id 对上，一次看全。","c":"产品岗","i":"post-pm"},{"n":"漏斗分析","a":"","d":"看用户从第一步走到最后一步，每一步剩多少人。","x":"像看一队人过五道门，每道门剩几个。","c":"产品岗","i":"post-pm"},{"n":"留存分析","a":"","d":"看不同时间来的用户，之后第几天还回来。","x":"像看不同批次入职的人，一个月后还剩几个。","c":"产品岗","i":"post-pm"},{"n":"用户分群","a":"","d":"按行为或属性把用户切成若干组，分别看分别运营。","x":"像把衣柜按季节分开放。","c":"产品岗","i":"post-pm"},{"n":"实验分流","a":"","d":"把流量按比例随机分给不同版本，保证两组人可比。","x":"像把一锅汤分两碗，随机决定哪碗加盐。","c":"产品岗","i":"post-pm"},{"n":"对照组","a":"","d":"不做改动的那一组，用来和改动组比出真实效果。","x":"像试新药时那组吃安慰剂的人。","c":"产品岗","i":"post-pm"},{"n":"显著性","a":"","d":"两组差异有多大把握不是运气造成的。","x":"像判断这次考试成绩提高是真进步还是碰巧题简单。","c":"产品岗","i":"post-pm"},{"n":"置信区间","a":"","d":"真实值大概率落在的那个范围，而不是一个精确点。","x":"像说「大概 30 到 40 分钟到」，而不是「32 分钟」。","c":"产品岗","i":"post-pm"},{"n":"样本量","a":"","d":"参与实验的人数够不够，太少结论不可信。","x":"像试菜只找两个人尝，说明不了问题。","c":"产品岗","i":"post-pm"},{"n":"假设检验","a":"","d":"用数据判断「这个差异是真的」还是「碰巧」。","x":"像法庭上先假设无罪，再看证据够不够推翻。","c":"产品岗","i":"post-pm"},{"n":"实验平台","a":"","d":"专门用来配实验、分流量、看结果的内部系统。","x":"像一块可以同时试种几块地的试验田。","c":"产品岗","i":"post-pm"},{"n":"开关配置","a":"","d":"把功能做成可远程开关的，出问题先关掉不用发版。","x":"像给新装的灯接个独立开关。","c":"产品岗","i":"post-pm"},{"n":"白名单","a":"","d":"只有名单里的人能用这个功能，用来小范围试。","x":"像只给内部员工发的内测邀请码。","c":"产品岗","i":"post-pm"},{"n":"灰度名单","a":"","d":"规定哪批用户先看到新版本，通常是内部人或特定城市。","x":"像新菜先在几家店试卖。","c":"产品岗","i":"post-pm"},{"n":"运营后台","a":"","d":"给内部同事用的管理界面，改配置、发内容、看数据。","x":"像店长用的那台后台收银机。","c":"产品岗","i":"post-pm"},{"n":"CMS","a":"内容管理系统","d":"专门用来编辑、审核、发布内容的后台系统。","x":"像报社的排版发稿系统。","c":"产品岗","i":"post-pm"},{"n":"审核流","a":"","d":"内容或配置要经过谁批、几步才能上线的那套流程。","x":"像报销单要组长、经理、财务一层层签。","c":"产品岗","i":"post-pm"},{"n":"权限角色","a":"","d":"把权限打包成角色，给人分配角色而不是逐个授权。","x":"像工牌颜色决定能进哪几道门。","c":"产品岗","i":"post-pm"},{"n":"审计日志","a":"","d":"谁在什么时候改了什么，全部留痕，事后能查。","x":"像监控录像，出事能倒回去看。","c":"产品岗","i":"post-pm"},{"n":"操作日志","a":"","d":"记录后台每一次点击和提交的流水。","x":"像收银机打出的每一笔小票。","c":"产品岗","i":"post-pm"},{"n":"批量导入","a":"","d":"一次上传一份表格导入成百上千条数据。","x":"像一次搬一整箱货，而不是一件件拿。","c":"产品岗","i":"post-pm"},{"n":"防重复提交","a":"","d":"用户连点两下只算一次，避免重复下单或重复扣款。","x":"像电梯按钮按一次就够，再按也不会来两部。","c":"产品岗","i":"post-pm"}]
